--
-- Name: _add_report_evidence(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._add_report_evidence(p_report uuid, p_log uuid, p_kind text, p_media jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  m jsonb;
begin
  if jsonb_array_length(coalesce(p_media, '[]'::jsonb)) > 6 then
    raise exception 'At most 6 photos';
  end if;
  for m in select * from jsonb_array_elements(coalesce(p_media, '[]'::jsonb)) loop
    insert into public.report_evidence (report_id, posted_by, kind, media_url, mime_type, bytes, log_id)
    values (p_report, auth.uid(), p_kind, m->>'media_url', m->>'mime_type', (m->>'bytes')::integer, p_log);
  end loop;
end $$;


--
-- Name: _case_guard(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._case_guard(p_report uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_h   uuid;
  v_name text;
begin
  if p_report is null or v_uid is null or not public.is_admin() then
    return;
  end if;
  if current_setting('smartsumbong.handler_change', true) = 'on' then
    return;
  end if;
  select handler_id into v_h from public.reports where id = p_report;
  if v_h is null then
    perform set_config('smartsumbong.handler_change', 'on', true);
    update public.reports set handler_id = v_uid, handled_since = now()
     where id = p_report and handler_id is null;
    insert into public.case_handler_log (report_id, admin_id, action) values (p_report, v_uid, 'take');
    perform set_config('smartsumbong.handler_change', 'off', true);
  elsif v_h <> v_uid then
    select public.display_name(full_name) into v_name from public.users where id = v_h;
    raise exception '% is handling this case. Take it over to act on it.', coalesce(v_name, 'Another administrator');
  end if;
end $$;


--
-- Name: _case_guard_report(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._case_guard_report() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_name text;
begin
  new.version := coalesce(old.version, 0) + 1;
  if v_uid is null or current_setting('smartsumbong.handler_change', true) = 'on' or not public.is_admin() then
    return new;
  end if;
  if old.handler_id is null then
    new.handler_id := v_uid;
    new.handled_since := now();
    insert into public.case_handler_log (report_id, admin_id, action) values (new.id, v_uid, 'take');
  elsif old.handler_id <> v_uid then
    select public.display_name(full_name) into v_name from public.users where id = old.handler_id;
    raise exception '% is handling this case. Take it over to act on it.', coalesce(v_name, 'Another administrator');
  end if;
  return new;
end $$;


--
-- Name: _case_guard_row(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._case_guard_row() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if tg_table_name = 'report_messages' then
    if new.from_barangay then perform public._case_guard(new.report_id); end if;
  elsif tg_table_name = 'dispatch_updates' then
    perform public._case_guard((select report_id from public.dispatches where id = new.dispatch_id));
  else
    perform public._case_guard(new.report_id);
  end if;
  return new;
end $$;


--
-- Name: _dispatch_cap_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._dispatch_cap_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare v_n int;
begin
  if new.state not in ('assigned', 'accepted') then return new; end if;
  if tg_op = 'UPDATE' and old.state in ('assigned', 'accepted') and old.tanod_id = new.tanod_id then
    return new;   -- the same live dispatch moving between live states
  end if;
  perform pg_advisory_xact_lock(hashtext('dispatch-cap:' || new.tanod_id::text));
  select count(*) into v_n from public.dispatches
   where tanod_id = new.tanod_id and state in ('assigned', 'accepted') and id <> new.id;
  if v_n >= public.tanod_dispatch_cap() then
    raise exception 'This tanod already has % dispatches, the most at once.', v_n;
  end if;
  return new;
end $$;


--
-- Name: _notify_admins(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._notify_admins(p_message text, p_subject uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  insert into public.notifications (user_id, kind, message, subject_user_id)
  select a.id, 'status_change', p_message, p_subject from public.users a
   where a.role = 'admin' and not coalesce(a.is_suspended, false);
$$;


--
-- Name: is_media_url(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_media_url(p_url text) RETURNS boolean
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $_$
  select p_url ~
    '^https://res\.cloudinary\.com/nwb2kryl/image/upload/v[0-9]+/(reports|ids|selfies|dispatch|avatars)/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(jpg|jpeg|png|webp)$'
      or p_url ~
    '^https://res\.cloudinary\.com/nwb2kryl/image/authenticated/v[0-9]+/(ids|selfies)/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(jpg|jpeg|png|webp)$'
$_$;


--
-- Name: FUNCTION is_media_url(p_url text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.is_media_url(p_url text) IS 'True only for delivery URLs in the barangay''s own Cloudinary cloud: public images under reports, ids, selfies, dispatch or avatars, or private (authenticated) images under ids or selfies (0110), with a UUIDv4 object name, an image extension, no signature and no query string. Mirrored by _pinnedUrl in mobile/core/lib/src/media_upload.dart.';


