--
-- Name: users; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.users (
    id uuid NOT NULL,
    full_name text NOT NULL,
    email text,
    mobile_number text NOT NULL,
    role public.user_role DEFAULT 'resident'::public.user_role NOT NULL,
    id_image_url text,
    verification_status public.verification_state DEFAULT 'pending'::public.verification_state NOT NULL,
    verification_submitted_at timestamp with time zone,
    verification_due_at timestamp with time zone,
    verified_at timestamp with time zone,
    verified_by uuid,
    rejection_reason text,
    duty_status public.duty_state,
    is_dispatchable boolean DEFAULT false NOT NULL,
    is_suspended boolean DEFAULT false NOT NULL,
    suspended_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    last_geom public.geography(Point,4326),
    last_location_at timestamp with time zone,
    selfie_url text,
    id_type public.id_document_type,
    verification_overdue_notified_at timestamp with time zone,
    must_change_password boolean DEFAULT false NOT NULL,
    address text,
    avatar_url text,
    ocr_detected_type public.id_document_type,
    ocr_flags text[] DEFAULT '{}'::text[] NOT NULL,
    ocr_extracted_name text,
    ocr_extracted_number text,
    ocr_processed_at timestamp with time zone,
    muted_notification_kinds public.notification_kind[] DEFAULT '{}'::public.notification_kind[] NOT NULL,
    ocr_rescan_requested_at timestamp with time zone,
    is_retired boolean DEFAULT false NOT NULL,
    retired_at timestamp with time zone,
    admin_handover_until timestamp with time zone,
    admin_handover_role public.user_role,
    admin_handover_successor_id uuid,
    removed_at timestamp with time zone,
    CONSTRAINT duty_only_for_tanod CHECK (((duty_status IS NULL) OR (role = 'tanod'::public.user_role))),
    CONSTRAINT users_address_check CHECK (((address IS NULL) OR (char_length(address) <= 200))),
    CONSTRAINT users_avatar_url_pinned CHECK (((avatar_url IS NULL) OR public.is_media_url(avatar_url))),
    CONSTRAINT users_id_image_url_pinned CHECK (((id_image_url IS NULL) OR public.is_media_url(id_image_url))),
    CONSTRAINT users_selfie_url_pinned CHECK (((selfie_url IS NULL) OR public.is_media_url(selfie_url)))
);


--
-- Name: COLUMN users.email; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.email IS 'Contact address, not a credential. Optional: many residents do not have one. Sign-in identity is derived from mobile_number — see public.auth_email_for(). Postgres allows multiple NULLs under a unique constraint, so the uniqueness of real addresses still holds.';


--
-- Name: COLUMN users.mobile_number; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.mobile_number IS 'The identity. Normalised to +639XXXXXXXXX at signup, unique, and the basis of the synthetic auth address. Changing it changes how the resident signs in.';


--
-- Name: COLUMN users.selfie_url; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.selfie_url IS 'Optional liveness photo. Nullable: the Register Account use case does not require it. See 0013 header.';


--
-- Name: COLUMN users.id_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.id_type IS 'Which document id_image_url photographs. Chosen by the applicant at signup and shown to the admin during verification — the check differs by document, so the label is part of the evidence. Null on accounts created before 0019.';


--
-- Name: COLUMN users.verification_overdue_notified_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.verification_overdue_notified_at IS 'When admins were told this account passed its two-hour verification window. Non-null suppresses further notices; cleared on re-entry to pending. Bookkeeping for sweep_overdue_verifications(), not a service-level record — verification_due_at is that.';


--
-- Name: COLUMN users.must_change_password; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.must_change_password IS 'Set when an administrator issues a temporary password. The client is required to force a change before allowing any other action.';


--
-- Name: COLUMN users.address; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.address IS 'Free text, resident-editable directly (0038) — a "how to find your house" line for the barangay, not a geocoded value anything spatial reads. Unlike full_name/mobile_number this is not identity evidence, so guard_privileged_user_fields() (0026) does not restrict it.';


--
-- Name: COLUMN users.avatar_url; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.avatar_url IS 'Resident-editable directly (0038), same pattern as email. Pinned to this project''s own Cloudinary account by users_avatar_url_pinned, same as id_image_url/selfie_url.';


--
-- Name: COLUMN users.ocr_detected_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.ocr_detected_type IS 'ID type OCR read off the photograph itself (header/keyword match), independent of id_type which is what the applicant selected in the dropdown. The two disagreeing is a flag, not an error — see ocr_flags.';


--
-- Name: COLUMN users.ocr_flags; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.ocr_flags IS 'Machine-generated triage flags from the Flutter client''s on-device OCR pass, e.g. type_mismatch, unreadable, name_mismatch, no_id_number. Advisory only: never gates verify_user_account, only orders/labels the admin''s queue. Empty array means OCR ran and raised nothing, NOT that OCR never ran — check ocr_processed_at for that.';


--
-- Name: COLUMN users.ocr_extracted_name; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.ocr_extracted_name IS 'Name OCR read off the ID photo, for the admin to eyeball against full_name. Not normalised, not used in any automated comparison beyond the name_mismatch flag the client itself may set.';


--
-- Name: COLUMN users.ocr_extracted_number; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.ocr_extracted_number IS 'ID number OCR read off the photo (e.g. license or PhilSys number), shown to the admin for their own manual cross-check. Never validated against any external registry — see this file''s header.';


--
-- Name: COLUMN users.ocr_processed_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.ocr_processed_at IS 'When the client''s OCR pass ran. Null means it never ran (older app build, permission denied, or skipped) — distinct from it having run and found nothing to flag.';


--
-- Name: COLUMN users.muted_notification_kinds; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.muted_notification_kinds IS 'Notification kinds this user does not want a phone push for. Never suppresses the public.notifications row itself -- only checked by send-dispatch-push before it calls FCM. See 0044.';


--
-- Name: COLUMN users.ocr_rescan_requested_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.ocr_rescan_requested_at IS 'Set by request_ocr_rescan() when an admin asks for a fresh OCR read on this account''s already-uploaded ID photo. Cleared by the resident''s own app (AuthService.submitIdOcrResult) once it has re-run on-device OCR and written a new result. Null means no re-check is pending.';


--
-- Name: COLUMN users.is_retired; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.is_retired IS 'Set only by finalize_retirement() on approval. Never a self-service flag — see 0052 header.';


--
-- Name: COLUMN users.retired_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.retired_at IS 'When an admin approved the retirement request. Null until then.';


--
-- Name: COLUMN users.admin_handover_until; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.admin_handover_until IS 'Set by promote_to_admin()''s optional handover window (0055). When reached, run_admin_handover_expirations() reverts this admin back to admin_handover_role automatically. Null outside an active handover.';


--
-- Name: COLUMN users.admin_handover_role; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.admin_handover_role IS 'Role this admin returns to when admin_handover_until passes -- captured at scheduling time, since an unattended sweep has no one to ask once the window actually ends.';


--
-- Name: COLUMN users.admin_handover_successor_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.admin_handover_successor_id IS 'Who this admin is training during the handover window. Display only -- the successor already has full, independent admin access from the moment they are promoted; this is not a permission gate.';


--
-- Name: _resolution_tanod(uuid, text, public.report_status); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._resolution_tanod(p_report uuid, p_remark text, p_new_status public.report_status) RETURNS public.users
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select u.*
    from public.dispatches d
    join public.users u on u.id = d.tanod_id
   where p_new_status = 'resolved'
     and d.report_id = p_report
     and d.state = 'resolved'
     and nullif(trim(d.field_report_text), '') is not null
     and trim(d.field_report_text) = trim(coalesce(p_remark, ''))
   order by d.resolved_at desc nulls last
   limit 1
$$;


--
-- Name: _temp_password(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._temp_password() RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_alpha text := 'ABCDEFGHJKLMNPQRSTUVWXYZ';
  v_digit text := '23456789';
  v       text := '';
  i       integer;
begin
  for i in 1..4 loop v := v || substr(v_alpha, 1 + floor(random() * length(v_alpha))::int, 1); end loop;
  v := v || '-';
  for i in 1..4 loop v := v || substr(v_digit, 1 + floor(random() * length(v_digit))::int, 1); end loop;
  v := v || '-';
  for i in 1..3 loop v := v || substr(v_alpha, 1 + floor(random() * length(v_alpha))::int, 1); end loop;
  return v;
end $$;


--
-- Name: accept_dispatch(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accept_dispatch(p_dispatch uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_report uuid; v_old report_status;
begin
  update public.dispatches
     set state = 'accepted', accepted_at = now(), is_primary = true
   where id = p_dispatch
     and tanod_id = auth.uid()
     and state = 'assigned'
  returning report_id into v_report;

  if v_report is null then
    raise exception 'Dispatch not found, not yours, or already actioned';
  end if;

  select status into v_old from public.reports where id = v_report;

  update public.reports set status = 'in_progress' where id = v_report;

  insert into public.status_logs (report_id, changed_by, old_status, new_status)
  values (v_report, auth.uid(), v_old, 'in_progress');
end $$;


