--
-- Name: account_audit_fingerprint(public.account_audit); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_audit_fingerprint(a public.account_audit) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select concat_ws('|',
    a.id::text, a.subject_id::text, coalesce(a.actor_id::text, ''),
    a.action, coalesce(a.detail, ''),
    to_char(a.created_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US'))
$$;


--
-- Name: account_directory(public.user_role); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_directory(p_role public.user_role) RETURNS TABLE(id uuid, full_name text, email text, mobile_number text, role public.user_role, verification_status public.verification_state, is_suspended boolean, duty_status public.duty_state, id_image_url text, selfie_url text, rejection_reason text, submitted_at timestamp with time zone, due_at timestamp with time zone, minutes_left integer, is_overdue boolean, holding_incident boolean, created_at timestamp with time zone, ocr_detected_type public.id_document_type, ocr_flags text[], ocr_extracted_name text, ocr_extracted_number text, abuse_strike_count integer, ocr_processed_at timestamp with time zone, ocr_rescan_requested_at timestamp with time zone, id_type public.id_document_type, suspended_reason text, is_retired boolean, retired_at timestamp with time zone, avatar_url text)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select u.id, u.full_name, u.email, u.mobile_number, u.role,
         u.verification_status, u.is_suspended, u.duty_status,
         u.id_image_url, u.selfie_url, u.rejection_reason,
         u.verification_submitted_at,
         u.verification_due_at,
         case when u.verification_status = 'pending' and u.verification_due_at is not null
              then (extract(epoch from (u.verification_due_at - now())) / 60)::integer
         end,
         u.verification_status = 'pending'
           and u.verification_due_at is not null
           and u.verification_due_at < now(),
         exists (select 1 from public.dispatches d
                  where d.tanod_id = u.id and d.state in ('assigned', 'accepted')),
         u.created_at,
         u.ocr_detected_type,
         u.ocr_flags,
         u.ocr_extracted_name,
         u.ocr_extracted_number,
         (select count(*)::integer from public.status_logs sl
           join public.reports r2 on r2.id = sl.report_id
          where r2.resident_id = u.id
            and sl.is_abusive = true
            and sl.new_status = 'rejected'),
         u.ocr_processed_at,
         u.ocr_rescan_requested_at,
         u.id_type,
         u.suspended_reason,
         u.is_retired,
         u.retired_at,
         u.avatar_url
    from public.users u
   where u.role = p_role
     and u.removed_at is null
   order by (u.verification_status = 'pending') desc,
            cardinality(u.ocr_flags) > 0 desc,
            u.verification_due_at nulls last,
            u.full_name
$$;


--
-- Name: FUNCTION account_directory(p_role public.user_role); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.account_directory(p_role public.user_role) IS 'Residents / Personnel list. Pending first, then flagged-by-OCR first within that, soonest deadline after. Carries id_type, suspended_reason (0051), is_retired/retired_at (0052) and now avatar_url (0054) so Personnel/Residents can show the same profile picture the mobile app Edit Profile screen lets someone set for themselves.';


--
-- Name: admin_barangay_update(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_barangay_update(p_report uuid, p_body text, p_media jsonb DEFAULT '[]'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_report public.reports%rowtype;
  v_body   text := nullif(trim(coalesce(p_body, '')), '');
  v_count  integer := jsonb_array_length(coalesce(p_media, '[]'::jsonb));
  v_log    uuid;
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may post a barangay update';
  end if;
  if v_body is null and v_count = 0 then
    raise exception 'Write an update or attach a photo';
  end if;
  if v_body is not null and char_length(v_body) > 500 then
    raise exception 'The update can be at most 500 characters';
  end if;

  select * into v_report from public.reports
   where id = p_report and deleted_at is null for update;
  if not found then
    raise exception 'No such report';
  end if;
  if v_report.status in ('pending_review', 'closed', 'archived', 'rejected', 'cancelled') then
    raise exception 'Updates can be posted on an accepted, open complaint';
  end if;

  insert into public.status_logs (report_id, changed_by, old_status, new_status, remark)
  values (p_report, auth.uid(), v_report.status, v_report.status,
          coalesce('Update from the barangay: ' || v_body,
                   format('The barangay added %s photo(s).', v_count)))
  returning id into v_log;

  perform public._add_report_evidence(p_report, v_log, 'update', p_media);

  insert into public.notifications (user_id, report_id, kind, message)
  values (v_report.resident_id, p_report, 'status_change',
          'Update on ' || v_report.tracking_id || ': '
          || coalesce(v_body, 'the barangay added photos.'));

  return v_log;
end $$;


--
-- Name: FUNCTION admin_barangay_update(p_report uuid, p_body text, p_media jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.admin_barangay_update(p_report uuid, p_body text, p_media jsonb) IS 'The admin posts an update, with up to 6 photos, to a complaint''s timeline and its resident, with or without a tanod on it (0079).';


--
-- Name: admin_candidates(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_candidates(p_search text DEFAULT NULL::text) RETURNS TABLE(id uuid, full_name text, email text, role public.user_role, mobile_number text)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select u.id, u.full_name, u.email, u.role, u.mobile_number
    from public.users u
   where u.verification_status = 'verified'
     and not u.is_suspended
     and u.role <> 'admin'
     and (p_search is null or trim(p_search) = ''
          or u.full_name ilike '%' || trim(p_search) || '%'
          or u.email     ilike '%' || trim(p_search) || '%')
   order by u.full_name
   limit 25
$$;


--
-- Name: FUNCTION admin_candidates(p_search text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.admin_candidates(p_search text) IS 'Verified, unsuspended, non-admin accounts. Verified means the barangay confirmed they live in 183.';


--
-- Name: admin_dispatch(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_dispatch(p_report uuid, p_tanod uuid, p_instructions text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_report   public.reports%rowtype;
  v_tanod    public.users%rowtype;
  v_busy     text;
  v_dispatch uuid;
  v_metres   double precision;
  v_note     text := nullif(trim(coalesce(p_instructions, '')), '');
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may assign a dispatch manually';
  end if;

  select * into v_report from public.reports where id = p_report and deleted_at is null;
  if not found then
    raise exception 'No such report';
  end if;

  -- Set, not necessarily future: a reroute of an overdue complaint comes
  -- through here too. The assign form itself only takes a future date.
  if v_report.due_at is null then
    raise exception 'Set a target resolution date before dispatching';
  end if;

  if v_note is null then
    raise exception 'Write instructions for the tanod before dispatching';
  end if;

  select * into v_tanod from public.users where id = p_tanod;
  if not found or v_tanod.role <> 'tanod' then
    raise exception 'That account is not a tanod';
  end if;

  if not v_tanod.is_dispatchable then
    raise exception '% is not available for dispatch (duty status: %)',
      v_tanod.full_name, coalesce(v_tanod.duty_status::text, 'not set');
  end if;

  select case when count(*) >= public.tanod_dispatch_cap() then max(r.subject) end into v_busy
    from public.dispatches d
    join public.reports r on r.id = d.report_id
   where d.tanod_id = p_tanod and d.state in ('assigned', 'accepted');

  if v_busy is not null then
    raise exception
      '% already has the most dispatches a tanod can hold at once. Choose another available tanod.',
      v_tanod.full_name;
  end if;

  select st_distance(v_tanod.last_geom, v_report.geom) into v_metres;

  insert into public.dispatches (report_id, tanod_id, assigned_by, admin_instructions)
  values (p_report, p_tanod, auth.uid(), v_note)
  returning id into v_dispatch;

  update public.reports
     set status = 'assigned', awaiting_unit_since = null
   where id = p_report;

  insert into public.status_logs (report_id, changed_by, old_status, new_status, remark)
  values (p_report, auth.uid(), v_report.status, 'assigned',
          case when v_metres is null
            then format('Manually assigned to %s by admin', v_tanod.full_name)
            else format('Manually assigned to %s by admin (%s m from the incident)',
                        v_tanod.full_name, round(v_metres))
          end);

  insert into public.notifications (user_id, report_id, kind, message)
  values (p_tanod, p_report, 'assignment',
          format('Assigned by the barangay admin: %s', v_report.subject));

  insert into public.notifications (user_id, report_id, kind, message)
  values (v_report.resident_id, p_report, 'assignment',
          format('A tanod has been dispatched to your report %s.', v_report.tracking_id));

  return v_dispatch;
end $$;


--
-- Name: admin_reroute_dispatch(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_reroute_dispatch(p_dispatch uuid, p_reason text, p_to uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_d      public.dispatches%rowtype;
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
  v_tick   text;
  v_next   uuid;
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may reroute a dispatch';
  end if;
  if v_reason is null then
    raise exception 'A reason is required to reroute a dispatch';
  end if;

  select * into v_d from public.dispatches
   where id = p_dispatch and state in ('assigned', 'accepted')
   for update;
  if not found then
    raise exception 'That dispatch is no longer active';
  end if;
  if p_to is not null and p_to = v_d.tanod_id then
    raise exception 'That tanod already has this dispatch';
  end if;

  update public.dispatches
     set state = 'rerouted', rerouted_at = now(),
         reroute_reason = 'By the barangay: ' || v_reason, rerouted_to = p_to
   where id = p_dispatch;

  select tracking_id into v_tick from public.reports where id = v_d.report_id;

  insert into public.status_logs (report_id, changed_by, old_status, new_status, remark)
  values (v_d.report_id, auth.uid(), 'assigned', 'assigned',
          'Rerouted by the barangay: ' || v_reason);

  insert into public.notifications (user_id, report_id, kind, message)
  values (v_d.tanod_id, v_d.report_id, 'reroute',
          format('The barangay moved %s to another tanod: %s', v_tick, v_reason));

  if p_to is not null then
    -- admin_dispatch checks the new tanod (on duty, not busy), sets the
    -- report to assigned, and notifies them and the resident. Any
    -- refusal there rolls this whole call back.
    v_next := public.admin_dispatch(v_d.report_id, p_to,
                                    'Rerouted by the barangay: ' || v_reason);
  else
    v_next := public.redispatch_report(v_d.report_id,
                                       'rerouted by the barangay: ' || v_reason);
  end if;

  return v_next;
end $$;


--
-- Name: FUNCTION admin_reroute_dispatch(p_dispatch uuid, p_reason text, p_to uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.admin_reroute_dispatch(p_dispatch uuid, p_reason text, p_to uuid) IS 'An admin moves a live dispatch to another tanod (p_to) or back to the system''s nearest-tanod routing (p_to null). Reason required. 0070.';


--
-- Name: admin_reset_password(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_reset_password(p_user uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'auth'
    AS $$
declare
  v_user    public.users%rowtype;
  v_temp    text;
  v_alpha   text := 'ABCDEFGHJKLMNPQRSTUVWXYZ';   -- no I or O
  v_digit   text := '23456789';                    -- no 0 or 1
  v_changed integer;
  i         integer;
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may reset a password';
  end if;

  select * into v_user from public.users where id = p_user for update;
  if not found then
    raise exception 'No such account';
  end if;

  if v_user.role = 'admin' then
    raise exception 'Administrator passwords are not reset through this path';
  end if;

  if v_user.is_suspended then
    raise exception 'This account is suspended. Lift the suspension first.';
  end if;

  -- Checked before anything is generated or written. An account with no
  -- sign-in record cannot be given a password, and the honest answer is
  -- that it has to be registered through the app first.
  if not exists (select 1 from auth.users where id = p_user) then
    raise exception
      'This account has never signed in and has no credential to reset. '
      'It must be registered through the app.';
  end if;

  v_temp := '';
  for i in 1..4 loop
    v_temp := v_temp || substr(v_alpha, 1 + floor(random() * length(v_alpha))::int, 1);
  end loop;
  v_temp := v_temp || '-';
  for i in 1..4 loop
    v_temp := v_temp || substr(v_digit, 1 + floor(random() * length(v_digit))::int, 1);
  end loop;
  v_temp := v_temp || '-';
  for i in 1..3 loop
    v_temp := v_temp || substr(v_alpha, 1 + floor(random() * length(v_alpha))::int, 1);
  end loop;

  update auth.users
     set encrypted_password = extensions.crypt(v_temp, extensions.gen_salt('bf')),
         updated_at         = now()
   where id = p_user;

  -- Not `if not found`. FOUND carries over from the SELECT above and
  -- reports true regardless of what this UPDATE did — which is exactly
  -- how 0028 handed out a password for an account it never touched.
  get diagnostics v_changed = row_count;
  if v_changed <> 1 then
    raise exception
      'The password was not changed (% rows affected). Nothing has been '
      'issued.', v_changed;
  end if;

  update public.users
     set must_change_password = true
   where id = p_user;

  insert into public.account_audit (subject_id, actor_id, action, detail)
  values (p_user, auth.uid(), 'password_reset',
          'Temporary password issued in person');

  return v_temp;
end $$;


--
-- Name: FUNCTION admin_reset_password(p_user uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.admin_reset_password(p_user uuid) IS 'Issues a temporary password for a resident or tanod and returns it to the calling administrator once. Never stored in plaintext.';


--
-- Name: admin_set_status(uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_set_status(p_report uuid, p_status text, p_remark text DEFAULT NULL::text, p_media jsonb DEFAULT '[]'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_report public.reports%rowtype;
  v_new    report_status;
  v_remark text := nullif(trim(coalesce(p_remark, '')), '');
  v_log    uuid;
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may change a complaint''s status';
  end if;
  if p_status not in ('in_progress', 'offline_investigation', 'resolved') then
    raise exception 'Choose In Progress, Offline Investigation or Resolved';
  end if;
  v_new := p_status::report_status;

  select * into v_report from public.reports
   where id = p_report and deleted_at is null for update;
  if not found then
    raise exception 'No such report';
  end if;
  if v_report.status in ('closed', 'archived', 'rejected', 'cancelled', 'pending_review') then
    raise exception 'This complaint''s status cannot be changed here';
  end if;
  if v_report.status = v_new then
    raise exception 'The complaint is already %', replace(p_status, '_', ' ');
  end if;

  if v_new = 'resolved' then
    update public.dispatches
       set state = 'rerouted', rerouted_at = now(), reroute_reason = 'Resolved by the barangay'
     where report_id = p_report and state in ('assigned', 'accepted');
    update public.reports
       set status = 'resolved', resolved_at = now(), resolution_submitted_at = null
     where id = p_report;
  else
    update public.reports set status = v_new where id = p_report;
  end if;

  insert into public.status_logs (report_id, changed_by, old_status, new_status, remark)
  values (p_report, auth.uid(), v_report.status, v_new,
          coalesce(v_remark, case v_new
            when 'in_progress' then 'Status set to In Progress by the barangay.'
            when 'offline_investigation' then 'Status set to Offline Investigation by the barangay.'
            else 'Marked resolved by the barangay.' end))
  returning id into v_log;

  perform public._add_report_evidence(p_report, v_log,
          case when v_new = 'resolved' then 'resolution' else 'update' end, p_media);

  insert into public.notifications (user_id, report_id, kind, message)
  values (v_report.resident_id, p_report, 'status_change',
          case v_new
            when 'in_progress' then 'Your complaint ' || v_report.tracking_id || ' is in progress.'
            when 'offline_investigation' then 'Your complaint ' || v_report.tracking_id || ' is under offline investigation by the barangay.'
            else 'Your complaint ' || v_report.tracking_id || ' has been resolved.' end
          || coalesce(' ' || v_remark, ''));
end $$;


--
-- Name: admin_update_user(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_update_user(p_user uuid, p_full_name text, p_email text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
declare
  v_user  public.users%rowtype;
  v_name  text := nullif(regexp_replace(trim(coalesce(p_full_name, '')), '\s+', ' ', 'g'), '');
  v_email text := nullif(lower(trim(coalesce(p_email, ''))), '');
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may correct a profile';
  end if;
  select * into v_user from public.users where id = p_user for update;
  if not found then
    raise exception 'No such account';
  end if;
  if v_user.role = 'admin' then
    raise exception 'Administrators edit their own profile under Edit Profile';
  end if;
  if v_name is null then
    raise exception 'Enter the full name';
  end if;
  if v_email is not null and v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then
    raise exception 'That email address does not look right';
  end if;
  if v_email is not null and exists (select 1 from public.users
                                      where lower(email) = v_email and id <> p_user) then
    raise exception 'Another account already uses that email address';
  end if;

  update public.users
     set full_name = v_name,
         email = coalesce(v_email, email)
   where id = p_user;

  insert into public.notifications (user_id, report_id, kind, message)
  values (p_user, null, 'verification',
          'The barangay corrected your profile details. Check them under Edit Profile.');
end $_$;


--
-- Name: appeal_report(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.appeal_report(p_report uuid, p_remark text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_report public.reports%rowtype;
  v_remark text := nullif(trim(coalesce(p_remark, '')), '');
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may act on an appeal';
  end if;

  select * into v_report
    from public.reports
   where id = p_report and deleted_at is null
     for update;

  if not found then
    raise exception 'No such report';
  end if;

  if v_report.status <> 'rejected' then
    raise exception 'Only a rejected complaint can be reinstated on appeal';
  end if;

  -- 0071: no fresh policy window; the admin sets the date when assigning.
  update public.reports
     set status      = 'validated',
         appealed_at = now(),
         due_at      = null
   where id = p_report;

  insert into public.status_logs (report_id, changed_by, old_status, new_status, remark)
  values (p_report, auth.uid(), 'rejected', 'validated',
          coalesce(v_remark, 'Appeal granted: reinstated for review.'));

  insert into public.notifications (user_id, report_id, kind, message)
  values (v_report.resident_id, p_report, 'status_change',
          format('Your appeal for %s was granted. It is back with the barangay.',
                 v_report.tracking_id));
end $$;


--
-- Name: FUNCTION appeal_report(p_report uuid, p_remark text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.appeal_report(p_report uuid, p_remark text) IS 'Grants a resident appeal: rejected back to validated, marks appealed_at, clears the target date for the admin to set again (0071), logs and notifies the resident. Admin only.';


--
-- Name: approve_escalation(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_escalation(p_request uuid, p_office text, p_note text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_r public.escalation_requests%rowtype;
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may decide an escalation request';
  end if;
  select * into v_r from public.escalation_requests where id = p_request for update;
  if not found or v_r.status <> 'pending' then
    raise exception 'That request has already been decided';
  end if;

  perform public.refer_report(v_r.report_id, p_office, p_note);

  update public.escalation_requests
     set decision_note = nullif(trim(coalesce(p_note, '')), '')
   where id = p_request;

  insert into public.notifications (user_id, report_id, kind, message)
  values (v_r.requested_by, v_r.report_id, 'status_change',
          'Your escalation request was approved: escalated to the ' || trim(p_office) || '.');
end $$;


--
-- Name: approve_resolution(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_resolution(p_report uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_report public.reports%rowtype;
  v_d      public.dispatches%rowtype;
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may approve a resolution';
  end if;
  select * into v_report from public.reports
   where id = p_report and deleted_at is null for update;
  if not found then
    raise exception 'No such report';
  end if;
  if v_report.resolution_submitted_at is null or v_report.status = 'resolved' then
    raise exception 'There is no resolution waiting for approval';
  end if;

  select * into v_d from public.dispatches
   where report_id = p_report and state = 'resolved'
   order by resolved_at desc nulls last limit 1;

  update public.reports
     set status = 'resolved', resolved_at = now(), resolution_submitted_at = null
   where id = p_report;

  -- The tanod's own words stay the resolution note the resident reads.
  insert into public.status_logs (report_id, changed_by, old_status, new_status, remark)
  values (p_report, auth.uid(), v_report.status, 'resolved',
          coalesce(nullif(trim(v_d.field_report_text), ''), 'Resolution approved by the barangay.'));

  insert into public.notifications (user_id, report_id, kind, message)
  values (v_report.resident_id, p_report, 'status_change',
          'Your complaint ' || v_report.tracking_id || ' has been resolved.');

  if v_d.tanod_id is not null then
    insert into public.notifications (user_id, report_id, kind, message)
    values (v_d.tanod_id, p_report, 'status_change',
            'The barangay approved your resolution of ' || v_report.tracking_id || '.');
  end if;
end $$;


--
-- Name: assert_not_client(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_not_client(p_what text) RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  if current_user in ('authenticated', 'anon') then
    raise exception '% may not be called directly. Administrators use admin_dispatch().', p_what;
  end if;
end $$;


--
-- Name: assign_tracking_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_tracking_id() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  if new.tracking_id is null then
    new.tracking_id := 'BRG-' || to_char(now(), 'YYYY') || '-' ||
                       lpad(nextval('public.report_seq')::text, 4, '0');
  end if;
  return new;
end $$;


--
-- Name: assignable_tanods(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assignable_tanods(p_report uuid) RETURNS TABLE(tanod_id uuid, full_name text, metres double precision, location_fresh boolean)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select u.id, u.full_name,
         st_distance(u.last_geom, r.geom),
         public.location_is_fresh(u.last_location_at)
    from public.reports r
    cross join public.users u
   where r.id = p_report
     and u.is_dispatchable
     and (select count(*) from public.dispatches d
           where d.tanod_id = u.id and d.state in ('assigned', 'accepted')) < public.tanod_dispatch_cap()
   order by st_distance(u.last_geom, r.geom) nulls last, u.full_name
$$;


--
-- Name: audit_integrity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_integrity() RETURNS TABLE(scope text, entries bigint, broken bigint, head_hash text)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_broken bigint := 0;
  v_bad    bigint;
  r        record;
begin
  for r in select distinct report_id from public.status_logs loop
    select count(*) filter (where not v.intact) into v_bad
      from public.verify_report_trail(r.report_id) v;
    v_broken := v_broken + coalesce(v_bad, 0);
  end loop;

  scope   := 'Complaint trail';
  select count(*) into entries from public.status_logs;
  broken  := v_broken;
  select entry_hash into head_hash from public.status_logs order by created_at desc, id desc limit 1;
  return next;

  scope   := 'Account changes';
  select count(*) into entries from public.account_audit;
  broken  := 0;
  select entry_hash into head_hash from public.account_audit order by created_at desc, id desc limit 1;
  return next;
end $$;


--
-- Name: FUNCTION audit_integrity(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.audit_integrity() IS 'Summary for the turnover pack. head_hash is the value worth printing on the monthly report — an outside copy is what makes a rebuilt chain detectable.';


--
-- Name: auth_email_for(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_email_for(p_mobile text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'public', 'extensions'
    AS $$
  select regexp_replace(p_mobile, '[^0-9]', '', 'g')
         || '@auth.smartsumbong.local'
$$;


--
-- Name: FUNCTION auth_email_for(p_mobile text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.auth_email_for(p_mobile text) IS 'The synthetic Supabase Auth address for a mobile number. Digits only, so +639171234567 and 09171234567 must already have been normalised to the same form by the client before they reach here.';


--
-- Name: auto_dispatch(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_dispatch(p_report uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_report     public.reports%rowtype;
  v_tanod      uuid;
  v_tanod_name text;
  v_metres     double precision;
  v_dispatch   uuid;
  v_system     uuid;
  v_last       text;
begin
  select * into v_report from public.reports where id = p_report;
  if not found then
    raise exception 'No such report';
  end if;

  -- NEW (0064): the newest remark on this report's trail, so a retry
  -- that changes nothing doesn't log the same line again.
  select remark into v_last
    from public.status_logs
   where report_id = p_report
   order by created_at desc
   limit 1;

  -- Out of jurisdiction: refer, do not dispatch.
  if not public.is_within_barangay(v_report.latitude, v_report.longitude) then
    update public.reports
       set escalation_level = greatest(escalation_level, 1),
           escalated_at = coalesce(escalated_at, now())
     where id = p_report;

    if v_last is distinct from 'Outside Barangay 183 — referred to city services' then
      insert into public.status_logs (report_id, changed_by, old_status, new_status,
                                      remark, is_system)
      values (p_report, v_report.resident_id, v_report.status, v_report.status,
              'Outside Barangay 183 — referred to city services', true);
    end if;
    return null;
  end if;

  select t.tanod_id, t.full_name, t.metres into v_tanod, v_tanod_name, v_metres
    from public.nearest_available_tanod(p_report) t limit 1;

  if v_tanod is null then
    if v_last is distinct from
         'No tanod available for automatic dispatch — awaiting manual assignment' then
      insert into public.status_logs (report_id, changed_by, old_status, new_status,
                                      remark, is_system)
      values (p_report, v_report.resident_id, v_report.status, v_report.status,
              'No tanod available for automatic dispatch — awaiting manual assignment', true);
    end if;
    return null;
  end if;

  -- assigned_by records the system, using the report's own admin-less
  -- path: attributed to the nearest tanod's own id would be wrong, so
  -- the first admin on record stands as the dispatching authority.
  select id into v_system from public.users where role = 'admin' order by created_at limit 1;

  insert into public.dispatches (report_id, tanod_id, assigned_by, admin_instructions)
  values (p_report, v_tanod, coalesce(v_system, v_tanod),
          case when v_metres is null
               then 'Automatic dispatch — on-duty unit; no location shared yet.'
               else format('Automatic dispatch — nearest available unit, %s m from the incident.',
                           round(v_metres)) end)
  returning id into v_dispatch;

  update public.reports set status = 'assigned' where id = p_report;

  -- NEW (0047): names the tanod, same pattern admin_dispatch already
  -- uses ("Manually assigned to %s by admin ...") -- the resident's
  -- timeline now answers "who is coming", not just "how far".
  insert into public.status_logs (report_id, changed_by, old_status, new_status,
                                  remark, is_system)
  values (p_report, coalesce(v_system, v_tanod), v_report.status, 'assigned',
          case when v_metres is null
               then format('Auto-dispatched to %s', v_tanod_name)
               else format('Auto-dispatched to %s (%s m away)', v_tanod_name, round(v_metres)) end, true);

  insert into public.notifications (user_id, report_id, kind, message)
  values (v_tanod, p_report, 'assignment',
          format('New dispatch: %s', v_report.subject));

  insert into public.notifications (user_id, report_id, kind, message)
  values (v_report.resident_id, p_report, 'assignment',
          format('A tanod has been dispatched to your report %s.', v_report.tracking_id));

  return v_dispatch;
end $$;


--
-- Name: FUNCTION auto_dispatch(p_report uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.auto_dispatch(p_report uuid) IS 'INTERNAL. Called by the on-file trigger, redispatch_report and the sweeps. Not callable by clients — administrators use admin_dispatch(). See 0016.';


--
-- Name: cancel_admin_handover(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_admin_handover() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may cancel a handover';
  end if;

  update public.users
     set admin_handover_until        = null,
         admin_handover_role         = null,
         admin_handover_successor_id = null
   where id = auth.uid();
end $$;


--
-- Name: FUNCTION cancel_admin_handover(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.cancel_admin_handover() IS 'Ends the caller''s own in-progress handover window immediately. Does not touch the successor''s admin access either way -- they keep it.';


--
-- Name: cancel_report(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_report(p_report uuid, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_old    report_status;
  v_owner  uuid;
begin
  -- No longer protected by reports_resident_read as invoker would be —
  -- SECURITY DEFINER bypasses RLS, so the ownership check right below is
  -- now the only thing standing between a resident and someone else's
  -- report. It was already here; it is now load-bearing rather than
  -- redundant.
  select status, resident_id
    into v_old, v_owner
    from public.reports
   where id = p_report and deleted_at is null;

  if v_old is null then
    raise exception 'Report not found';
  end if;

  if v_owner is distinct from auth.uid() then
    raise exception 'Only the resident who filed a report may cancel it';
  end if;

  if v_old not in ('pending_review', 'validated') then
    raise exception
      'This report can no longer be cancelled because the barangay has '
      'already started working on it';
  end if;

  update public.reports
     set status = 'cancelled',
         closed_at = now()
   where id = p_report;

  insert into public.status_logs
    (report_id, changed_by, old_status, new_status, remark)
  values
    (p_report, auth.uid(), v_old, 'cancelled',
     coalesce(nullif(trim(p_reason), ''), 'Withdrawn by the resident'));
end $$;


--
-- Name: FUNCTION cancel_report(p_report uuid, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.cancel_report(p_report uuid, p_reason text) IS 'Lets the resident who filed a complaint withdraw it, but only before anyone is working on it — pending_review or validated. SECURITY DEFINER (0030): the reports UPDATE and status_logs INSERT both need privileges RLS gives only admins and the DEFINER transition functions (see status_logs_insert in 0003) — the explicit ownership check below is what makes that safe, not RLS.';


--
-- Name: chain_account_audit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chain_account_audit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_prev text;
begin
  select entry_hash into v_prev
    from public.account_audit
   order by created_at desc, id desc
   limit 1;

  new.prev_hash  := coalesce(v_prev, repeat('0', 64));
  new.entry_hash := encode(
    extensions.digest(new.prev_hash || '|' || public.account_audit_fingerprint(new), 'sha256'), 'hex');
  return new;
end $$;


--
-- Name: chain_status_log(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chain_status_log() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_prev text;
begin
  -- One writer per complaint trail at a time.
  perform pg_advisory_xact_lock(hashtextextended('status_logs:' || new.report_id::text, 0));

  -- The head: the newest entry no other entry links to yet.
  select s.entry_hash into v_prev
    from public.status_logs s
   where s.report_id = new.report_id
     and not exists (select 1 from public.status_logs t
                      where t.report_id = s.report_id and t.prev_hash = s.entry_hash)
   order by s.created_at desc, s.id desc
   limit 1;

  new.prev_hash  := coalesce(v_prev, repeat('0', 64));
  new.entry_hash := encode(
    extensions.digest(new.prev_hash || '|' || public.status_log_fingerprint(new), 'sha256'), 'hex');
  return new;
end $$;


--
-- Name: check_login_lockout(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_login_lockout(p_mobile text) RETURNS TABLE(locked boolean, seconds_remaining integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
declare
  v_locked_until timestamptz;
begin
  if p_mobile is null or p_mobile !~ '^\+63[0-9]{10}$' then
    return query select false, 0;
    return;
  end if;

  select la.locked_until into v_locked_until
    from public.login_attempts la
   where la.mobile_number = p_mobile;

  if v_locked_until is not null and v_locked_until > now() then
    return query select true,
      greatest(0, ceil(extract(epoch from (v_locked_until - now())))::int);
  else
    return query select false, 0;
  end if;
end $_$;


--
-- Name: FUNCTION check_login_lockout(p_mobile text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.check_login_lockout(p_mobile text) IS 'Call before attempting sign-in. True + seconds remaining if this number is currently locked; false otherwise. Malformed input is treated as never-locked rather than raising, since the caller is about to fail its own normalisation check anyway.';


--
-- Name: clear_login_attempts(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clear_login_attempts(p_mobile text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  -- Only your own number, and only once signed in: the app calls this
  -- right after a successful sign-in, never before.
  delete from public.login_attempts la
   using public.users u
   where u.id = (select auth.uid())
     and u.mobile_number = p_mobile
     and la.mobile_number = p_mobile;
end $$;


--
-- Name: FUNCTION clear_login_attempts(p_mobile text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.clear_login_attempts(p_mobile text) IS 'Call once sign-in succeeds. 0107: clears only the signed-in caller''s own number; anyone else''s, or a call made while signed out, does nothing.';


--
-- Name: clear_password_change_flag(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clear_password_change_flag() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'Not signed in';
  end if;

  update public.users
     set must_change_password = false
   where id = auth.uid();
end $$;


--
-- Name: confirm_synthetic_auth_email(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_synthetic_auth_email() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  -- Only the derived domain. A real address created for an admin by
  -- hand keeps whatever confirmation flow it came with.
  if new.email like '%@auth.smartsumbong.local'
     and new.email_confirmed_at is null then
    new.email_confirmed_at := now();
  end if;
  return new;
end $$;


--
-- Name: FUNCTION confirm_synthetic_auth_email(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.confirm_synthetic_auth_email() IS 'Marks derived auth addresses confirmed at creation. They cannot receive mail — .local is unresolvable — so an unconfirmed one is an account that can never sign in. Identity is verified by the barangay admin against ID and selfie, not by proving control of a mailbox that does not exist.';


--
-- Name: create_admin_account(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_admin_account(p_email text, p_full_name text, p_mobile text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'auth'
    AS $_$
declare
  v_email  text := lower(trim(coalesce(p_email, '')));
  v_name   text := trim(coalesce(p_full_name, ''));
  v_mobile text := trim(coalesce(p_mobile, ''));
  v_id     uuid := gen_random_uuid();
  v_temp   text := public._temp_password();
  v_comma  int;
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may add an administrator';
  end if;
  if v_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then
    raise exception 'Enter a valid email address';
  end if;
  v_comma := position(',' in v_name);
  if v_comma <= 1 or length(trim(substring(v_name from v_comma + 1))) = 0 then
    raise exception 'Write the name as Last Name, First Name';
  end if;
  if v_mobile ~ '^09[0-9]{9}$' then
    v_mobile := '+63' || substr(v_mobile, 2);
  end if;
  if v_mobile !~ '^\+639[0-9]{9}$' then
    raise exception 'Enter the mobile number as 09XXXXXXXXX';
  end if;
  if exists (select 1 from auth.users where lower(email) = v_email)
     or exists (select 1 from public.users where lower(email) = v_email) then
    raise exception 'That email already has an account';
  end if;
  if exists (select 1 from public.users where mobile_number = v_mobile) then
    raise exception 'That mobile number already has an account';
  end if;

  perform set_config('smartsumbong.provisioning_admin', 'on', true);

  insert into auth.users (instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,
                          raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
                          confirmation_token, recovery_token, email_change_token_new, email_change)
  values ('00000000-0000-0000-0000-000000000000', v_id, 'authenticated', 'authenticated', v_email,
          extensions.crypt(v_temp, extensions.gen_salt('bf')), now(),
          '{"provider":"email","providers":["email"]}'::jsonb,
          jsonb_build_object('full_name', v_name), now(), now(), '', '', '', '');

  insert into auth.identities (id, provider_id, user_id, identity_data, provider, created_at, updated_at)
  values (gen_random_uuid(), v_id::text, v_id,
          jsonb_build_object('sub', v_id::text, 'email', v_email, 'email_verified', true),
          'email', now(), now());

  perform set_config('smartsumbong.provisioning_admin', 'off', true);

  insert into public.users (id, full_name, email, mobile_number, role,
                            verification_status, verified_at, verified_by, must_change_password)
  values (v_id, v_name, v_email, v_mobile, 'admin', 'verified', now(), auth.uid(), true);

  insert into public.account_audit (subject_id, actor_id, action, detail)
  values (v_id, auth.uid(), 'admin_created', 'Administrator account created with a temporary password');

  return v_temp;
end $_$;


--
-- Name: dashboard_metrics(timestamp with time zone, timestamp with time zone, public.complaint_category); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dashboard_metrics(p_from timestamp with time zone, p_to timestamp with time zone, p_category public.complaint_category DEFAULT NULL::public.complaint_category) RETURNS json
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_out json;
begin
  if p_from is null or p_to is null or p_to <= p_from then
    raise exception 'Invalid reporting period';
  end if;

  with scoped as (
    select r.*,
           -- "Finished" covers resolved and closed alike: a complaint
           -- the barangay has dealt with, whether or not the resident
           -- has since confirmed it.
           (r.status in ('resolved', 'closed', 'archived'))         as is_done,
           coalesce(r.resolved_at, r.closed_at)                     as finished_at
      from public.reports r
     where r.deleted_at is null
       and r.created_at >= p_from
       and r.created_at <  p_to
  ),
  classified as (
    select s.*,
           case
             -- Sent to an outside office (0072): neither resolved here
             -- nor still open.
             when s.referred_to is not null                then 'referred'
             -- Finished after the deadline it was given.
             when s.is_done and s.due_at is not null
                  and s.finished_at > s.due_at              then 'late'
             -- Finished in time, or finished with no deadline set.
             when s.is_done                                then 'done'
             -- Still open and the deadline has passed.
             when s.due_at is not null and now() > s.due_at then 'overdue'
             -- Still open, still inside the window. Rejected complaints
             -- are not work in progress and are counted separately.
             when s.status = 'rejected'                    then 'rejected'
             else                                               'processing'
           end as bucket
      from scoped s
  )
  select json_build_object(

    'period', json_build_object('from', p_from, 'to', p_to),

    'total', (select count(*) from scoped),

    -- Reports filed per calendar day, Manila time, with empty days
    -- present as zeroes so the line does not lie by skipping them.
    'daily', (
      select coalesce(json_agg(json_build_object(
               'day',   to_char(d.day, 'YYYY-MM-DD'),
               'label', to_char(d.day, 'FMDD'),
               'filed', coalesce(c.n, 0)) order by d.day), '[]'::json)
        from generate_series(
               (p_from at time zone 'Asia/Manila')::date,
               (p_to   at time zone 'Asia/Manila')::date - 1,
               interval '1 day') as d(day)
        left join (
          select (created_at at time zone 'Asia/Manila')::date as day, count(*) as n
            from scoped group by 1) c on c.day = d.day::date
    ),

    'resolution_status', (
      select json_build_object(
               'done',       count(*) filter (where bucket = 'done'),
               'overdue',    count(*) filter (where bucket = 'overdue'),
               'late',       count(*) filter (where bucket = 'late'),
               'processing', count(*) filter (where bucket = 'processing'),
               'rejected',   count(*) filter (where bucket = 'rejected'),
               'referred',   count(*) filter (where bucket = 'referred'))
        from classified
    ),

    'categories', (
      select coalesce(json_agg(json_build_object(
               'category', category, 'n', n) order by n desc, category), '[]'::json)
        from (select category::text as category, count(*) as n
                from scoped group by 1) t
    ),

    -- The three counters. Resolved and escalated are counts; the third
    -- is every complaint whose deadline has passed with nobody having
    -- finished it, which is the number an admin actually needs to see.
    'tiles', (
      select json_build_object(
               'resolved',  count(*) filter (where bucket in ('done', 'late')),
               -- 0072: escalated now means referred outside the barangay;
               -- the key keeps its name for the dashboard's sake.
               'escalated', count(*) filter (where bucket = 'referred'),
               'overdue',   count(*) filter (where bucket = 'overdue'))
        from classified
    ),

    -- Resolution efficiency: for each day, the mean hours between filing
    -- and finishing for the complaints finished that day, against the
    -- policy window they were held to. Two lines, one chart — "we took
    -- 31 hours" means nothing without "we were allowed 48". p_category
    -- (0056), when given, narrows this one chart only — every other key
    -- above is computed from the unfiltered `scoped`/`classified` CTEs.
    'efficiency', (
      select coalesce(json_agg(json_build_object(
               'day',     to_char(d.day, 'YYYY-MM-DD'),
               'label',   to_char(d.day, 'FMDD'),
               'actual',  e.avg_hours,
               'allowed', e.avg_target,
               'n',       coalesce(e.n, 0)) order by d.day), '[]'::json)
        from generate_series(
               (p_from at time zone 'Asia/Manila')::date,
               (p_to   at time zone 'Asia/Manila')::date - 1,
               interval '1 day') as d(day)
        left join (
          select (c.finished_at at time zone 'Asia/Manila')::date as day,
                 count(*) as n,
                 round(avg(extract(epoch from (c.finished_at - c.created_at)) / 3600)::numeric, 1)
                   as avg_hours,
                 round(avg(p.resolution_hours)::numeric, 1) as avg_target
            from classified c
            join public.sla_policies p on p.category = c.category
           where c.finished_at is not null
             and (p_category is null or c.category = p_category)
           group by 1) e on e.day = d.day::date
    )

  ) into v_out;

  return v_out;
end $$;


--
-- Name: FUNCTION dashboard_metrics(p_from timestamp with time zone, p_to timestamp with time zone, p_category public.complaint_category); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.dashboard_metrics(p_from timestamp with time zone, p_to timestamp with time zone, p_category public.complaint_category) IS 'Every figure on the analytics dashboard in one pass. Runs with the caller''s rights, so RLS decides what is counted. p_category (0056) narrows the efficiency chart only.';


--
-- Name: decide_profile_request(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decide_profile_request(p_request uuid, p_approve boolean, p_note text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  r      public.profile_requests%rowtype;
  v_note text := nullif(trim(coalesce(p_note, '')), '');
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may decide a profile request';
  end if;
  select * into r from public.profile_requests where id = p_request for update;
  if not found then
    raise exception 'No such request';
  end if;
  if r.status <> 'pending' then
    raise exception 'This request has already been decided';
  end if;
  if not p_approve and v_note is null then
    raise exception 'Give a reason for declining; the person sees it';
  end if;

  if p_approve then
    if r.kind = 'full_name' then
      update public.users set full_name = r.new_full_name where id = r.user_id;
    else
      update public.users set id_image_url = r.id_image_url, id_type = r.id_type where id = r.user_id;
    end if;
  end if;

  update public.profile_requests
     set status = case when p_approve then 'approved' else 'declined' end,
         decided_by = auth.uid(), decided_at = now(), decision_note = v_note
   where id = p_request;

  insert into public.account_audit (subject_id, actor_id, action, detail)
  values (r.user_id, auth.uid(),
          case r.kind when 'full_name' then 'name_change_' else 'id_reupload_' end || case when p_approve then 'approved' else 'declined' end,
          case r.kind when 'full_name' then 'Name change to ' || r.new_full_name else 'New ID photo' end
          || case when p_approve then ' approved' else ' declined' end || coalesce(': ' || v_note, ''));

  insert into public.notifications (user_id, kind, message)
  values (r.user_id, 'status_change',
          case r.kind when 'full_name' then 'Your name change' else 'Your new ID photo' end
          || case when p_approve then ' was approved by the barangay.' else ' was not approved' || coalesce(': ' || v_note, '.') end);
end $$;


--
-- Name: deny_escalation(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deny_escalation(p_request uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_r      public.escalation_requests%rowtype;
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
  v_tick   text;
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may decide an escalation request';
  end if;
  if v_reason is null then
    raise exception 'A reason is required to deny an escalation request';
  end if;
  select * into v_r from public.escalation_requests where id = p_request for update;
  if not found or v_r.status <> 'pending' then
    raise exception 'That request has already been decided';
  end if;

  update public.escalation_requests
     set status = 'denied', decided_by = auth.uid(), decided_at = now(),
         decision_note = v_reason
   where id = p_request;

  select tracking_id into v_tick from public.reports where id = v_r.report_id;

  -- The complaint stays with the barangay, in progress.
  insert into public.status_logs (report_id, changed_by, old_status, new_status, remark)
  select v_r.report_id, auth.uid(), r.status, r.status,
         'Escalation request denied: ' || v_reason
    from public.reports r where r.id = v_r.report_id;

  if v_r.dispatch_id is not null then
    insert into public.dispatch_updates (dispatch_id, author_id, kind, body)
    values (v_r.dispatch_id, auth.uid(), 'note', 'Escalation request denied: ' || v_reason);
  end if;

  insert into public.notifications (user_id, report_id, kind, message)
  values (v_r.requested_by, v_r.report_id, 'status_change',
          'Your escalation request for ' || v_tick || ' was denied: ' || left(v_reason, 140));
end $$;


--
-- Name: dispatch_on_file(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dispatch_on_file() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_auto boolean;
begin
  select auto_dispatch_on_file into v_auto
    from public.sla_policies where category = new.category;

  if coalesce(v_auto, false) then
    perform public.auto_dispatch(new.id);
  end if;

  return null;
end $$;


--
-- Name: FUNCTION dispatch_on_file(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.dispatch_on_file() IS 'Fires at COMMIT, not at INSERT, so that a complaint filed through file_report() has its photos attached before a tanod is dispatched to it.';


--
-- Name: display_name(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.display_name(p_name text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select case when position(',' in coalesce(p_name, '')) > 1
              then trim(substring(p_name from position(',' in p_name) + 1)) || ' ' || trim(split_part(p_name, ',', 1))
              else p_name end
$$;


--
-- Name: end_sessions_on_access_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.end_sessions_on_access_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
begin
  delete from auth.sessions where user_id = new.id;
  return new;
end $$;


--
-- Name: FUNCTION end_sessions_on_access_change(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.end_sessions_on_access_change() IS '0108: ends every session of a user whose password was reset by the barangay, or who was suspended or retired.';


--
-- Name: enforce_daily_report_limit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_daily_report_limit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_limit integer;
begin
  if new.resident_id is null or new.resident_id is distinct from (select auth.uid()) then
    return new;  -- not a resident filing for themselves (jobs, tests as postgres)
  end if;
  select max_reports_per_day into v_limit from public.operational_settings where id = 1;
  if (select count(*) from public.reports r
       where r.resident_id = new.resident_id
         and r.created_at > now() - interval '24 hours') >= coalesce(v_limit, 20) then
    raise exception 'You have filed % reports in the last 24 hours, the most allowed. Please try again tomorrow, or visit the barangay hall.', coalesce(v_limit, 20)
      using errcode = 'check_violation';
  end if;
  return new;
end $$;


--
-- Name: enforce_media_cap(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_media_cap() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  total integer;
begin
  select coalesce(sum(bytes), 0) into total
    from public.report_media where report_id = new.report_id;
  if total + new.bytes > 35 * 1024 * 1024 then
    raise exception 'Combined media for this report exceeds the 35 MB limit';
  end if;
  return new;
end $$;


--
-- Name: extensions_used(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.extensions_used(p_report uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select count(*)::integer
    from public.sla_extensions e
    join public.reports r on r.id = e.report_id
   where e.report_id = p_report
     and e.created_at > coalesce(r.handed_up_at, '-infinity'::timestamptz)
$$;


--
-- Name: reports; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.reports (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tracking_id text NOT NULL,
    resident_id uuid NOT NULL,
    is_anonymous boolean DEFAULT false NOT NULL,
    category public.complaint_category NOT NULL,
    subject text NOT NULL,
    description text NOT NULL,
    latitude double precision NOT NULL,
    longitude double precision NOT NULL,
    geom public.geography(Point,4326) GENERATED ALWAYS AS ((public.st_setsrid(public.st_makepoint(longitude, latitude), 4326))::public.geography) STORED,
    status public.report_status DEFAULT 'pending_review'::public.report_status NOT NULL,
    due_at timestamp with time zone,
    escalated_at timestamp with time zone,
    escalation_level smallint DEFAULT 0 NOT NULL,
    reopened_count smallint DEFAULT 0 NOT NULL,
    resolved_at timestamp with time zone,
    closed_at timestamp with time zone,
    deleted_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    dispatch_attempts smallint DEFAULT 0 NOT NULL,
    awaiting_unit_since timestamp with time zone,
    appealed_at timestamp with time zone,
    client_ref uuid,
    location_label text,
    referred_to text,
    referral_note text,
    referred_at timestamp with time zone,
    referred_by uuid,
    overdue_notified_at timestamp with time zone,
    followed_up_at timestamp with time zone,
    follow_up_count integer DEFAULT 0 NOT NULL,
    resolution_submitted_at timestamp with time zone,
    resolution_returned_reason text,
    is_public boolean DEFAULT false NOT NULL,
    higher_official text,
    higher_official_note text,
    handed_up_at timestamp with time zone,
    handler_id uuid,
    handled_since timestamp with time zone,
    version bigint DEFAULT 0 NOT NULL,
    CONSTRAINT reports_description_check CHECK (((char_length(description) >= 10) AND (char_length(description) <= 2000))),
    CONSTRAINT reports_escalation_level_check CHECK (((escalation_level >= 0) AND (escalation_level <= 3))),
    CONSTRAINT reports_higher_official_check CHECK (((char_length(higher_official) >= 2) AND (char_length(higher_official) <= 80))),
    CONSTRAINT reports_higher_official_note_check CHECK ((char_length(higher_official_note) <= 300)),
    CONSTRAINT reports_latitude_check CHECK (((latitude >= ('-90'::integer)::double precision) AND (latitude <= (90)::double precision))),
    CONSTRAINT reports_location_label_check CHECK (((location_label IS NULL) OR ((char_length(location_label) >= 1) AND (char_length(location_label) <= 160)))),
    CONSTRAINT reports_longitude_check CHECK (((longitude >= ('-180'::integer)::double precision) AND (longitude <= (180)::double precision))),
    CONSTRAINT reports_reopened_count_check CHECK ((reopened_count >= 0)),
    CONSTRAINT reports_subject_check CHECK (((char_length(subject) >= 3) AND (char_length(subject) <= 150)))
);

ALTER TABLE ONLY public.reports REPLICA IDENTITY FULL;


--
-- Name: COLUMN reports.awaiting_unit_since; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.reports.awaiting_unit_since IS 'Set when automatic dispatch found no available tanod. Cleared once a dispatch is created. Not a failure — the sweep keeps retrying while this is set.';


--
-- Name: COLUMN reports.appealed_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.reports.appealed_at IS 'Set once, by appeal_report() (0057), the first time a rejected complaint is reinstated on appeal. Never cleared or incremented — a marker, not a counter (see reopened_count for why appeals do not share it).';


--
-- Name: COLUMN reports.client_ref; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.reports.client_ref IS 'Client-generated id of the submission (resident app outbox). Unique per resident, so a resent report returns the one already filed instead of creating a duplicate. Null for reports filed without one.';


--
-- Name: COLUMN reports.location_label; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.reports.location_label IS 'Nearest street/place from OpenStreetMap reverse geocoding (0068). Display only; latitude/longitude stay the record.';


--
-- Name: COLUMN reports.referred_to; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.reports.referred_to IS 'The outside authority the admin referred this complaint to (0072), e.g. VAWC Desk. Set together with status closed.';


--
-- Name: COLUMN reports.higher_official; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.reports.higher_official IS 'The barangay official the case was handed to after its extensions ran out (0079). The case stays open here, under that official.';


--
-- Name: file_report(public.complaint_category, text, text, double precision, double precision, boolean, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.file_report(p_category public.complaint_category, p_subject text, p_description text, p_latitude double precision, p_longitude double precision, p_is_anonymous boolean DEFAULT false, p_media jsonb DEFAULT '[]'::jsonb, p_client_ref uuid DEFAULT NULL::uuid) RETURNS public.reports
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_report public.reports;
  v_item   jsonb;
begin
  if jsonb_typeof(coalesce(p_media, '[]'::jsonb)) <> 'array' then
    raise exception 'p_media must be a JSON array of {media_url, mime_type, bytes}'
      using errcode = 'invalid_parameter_value';
  end if;

  -- Already filed under this ref: hand back that report, file nothing.
  if p_client_ref is not null then
    select * into v_report
      from public.reports
     where resident_id = auth.uid()
       and client_ref = p_client_ref;
    if found then
      return v_report;
    end if;
  end if;

  begin
    insert into public.reports
      (resident_id, is_anonymous, category, subject, description,
       latitude, longitude, client_ref)
    values
      (auth.uid(), coalesce(p_is_anonymous, false), p_category,
       p_subject, p_description, p_latitude, p_longitude, p_client_ref)
    returning * into v_report;
  exception when unique_violation then
    -- Two sends of the same queued report raced; the other one won.
    select * into v_report
      from public.reports
     where resident_id = auth.uid()
       and client_ref = p_client_ref;
    return v_report;
  end;

  for v_item in select value from jsonb_array_elements(coalesce(p_media, '[]'::jsonb))
  loop
    insert into public.report_media (report_id, media_url, mime_type, bytes)
    values (v_report.id,
            v_item ->> 'media_url',
            v_item ->> 'mime_type',
            (v_item ->> 'bytes')::integer);
  end loop;

  return v_report;
end $$;


--
-- Name: FUNCTION file_report(p_category public.complaint_category, p_subject text, p_description text, p_latitude double precision, p_longitude double precision, p_is_anonymous boolean, p_media jsonb, p_client_ref uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.file_report(p_category public.complaint_category, p_subject text, p_description text, p_latitude double precision, p_longitude double precision, p_is_anonymous boolean, p_media jsonb, p_client_ref uuid) IS 'Submit Complaint Report, one transaction. SECURITY INVOKER: reports_resident_insert still decides whether this caller may file, and report_media_insert still decides whether these photos may attach. If any photo row is rejected the whole complaint rolls back, so a complaint is never stored with its evidence silently missing. p_client_ref (0066) makes a resend of the same submission return the report already filed.';


--
-- Name: finalize_retirement(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_retirement(p_request uuid, p_decision text, p_reason text DEFAULT NULL::text) RETURNS public.retirement_status
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_req    public.retirement_requests%rowtype;
  v_user   public.users%rowtype;
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
  v_new    retirement_status;
  d        record;
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may decide a retirement request';
  end if;

  if p_decision not in ('approve', 'deny') then
    raise exception 'Unknown decision: %', p_decision;
  end if;

  select * into v_req from public.retirement_requests where id = p_request for update;
  if not found then
    raise exception 'No such retirement request';
  end if;

  if v_req.status <> 'pending' then
    raise exception 'This request has already been decided (current status: %)',
      v_req.status;
  end if;

  if p_decision = 'deny' and v_reason is null then
    raise exception 'A reason is required when denying a retirement request';
  end if;

  select * into v_user from public.users where id = v_req.tanod_id for update;
  if not found then
    raise exception 'That tanod account no longer exists';
  end if;

  v_new := case p_decision when 'approve' then 'approved' else 'denied' end::retirement_status;

  update public.retirement_requests
     set status        = v_new,
         decided_at    = now(),
         decided_by    = auth.uid(),
         denial_reason = v_reason
   where id = p_request;

  if v_new = 'approved' then
    update public.users
       set is_retired  = true,
           retired_at  = now(),
           duty_status = null
     where id = v_user.id;

    -- Same protection set_account_suspension gives a suspended tanod
    -- (0013): a live dispatch cannot be left on a phone that is about
    -- to stop being checked.
    for d in
      update public.dispatches
         set state = 'expired'
       where tanod_id = v_user.id and state in ('assigned', 'accepted')
      returning report_id
    loop
      perform public.redispatch_report(d.report_id, 'assigned tanod has retired');
    end loop;
  end if;

  insert into public.notifications (user_id, kind, message)
  values (v_user.id, 'retirement',
          case v_new
            when 'approved' then
              'Your retirement has been approved. Thank you for your service — this account can no longer sign in.'
            else
              format('Your retirement request was not approved. Reason: %s', v_reason)
          end);

  return v_new;
end $$;


--
-- Name: FUNCTION finalize_retirement(p_request uuid, p_decision text, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.finalize_retirement(p_request uuid, p_decision text, p_reason text) IS 'Manage Retirement Request, admin only. Approve sets is_retired/retired_at and releases any live dispatch, mirroring set_account_suspension exactly.';


--
-- Name: follow_up_report(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.follow_up_report(p_report uuid, p_message text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_report public.reports%rowtype;
  v_msg    text := nullif(trim(coalesce(p_message, '')), '');
begin
  select * into v_report from public.reports
   where id = p_report and resident_id = auth.uid() and deleted_at is null
   for update;
  if not found then
    raise exception 'Complaint not found';
  end if;
  if v_report.status in ('resolved', 'closed', 'archived', 'rejected', 'cancelled') then
    raise exception 'This complaint is already finished';
  end if;
  if v_report.due_at is null or v_report.due_at > now() then
    raise exception 'You can follow up once the target date has passed';
  end if;
  if v_report.followed_up_at is not null
     and v_report.followed_up_at > now() - interval '24 hours' then
    raise exception 'You already followed up today. The barangay has been told.';
  end if;
  if v_msg is not null and char_length(v_msg) > 1000 then
    raise exception 'Keep the message under 1000 characters';
  end if;

  update public.reports
     set followed_up_at = now(), follow_up_count = follow_up_count + 1
   where id = p_report;

  insert into public.status_logs (report_id, changed_by, old_status, new_status, remark)
  values (p_report, auth.uid(), v_report.status, v_report.status,
          'The resident followed up on this overdue complaint.');

  if v_msg is not null then
    insert into public.report_messages (report_id, author_id, from_barangay, body)
    values (p_report, auth.uid(), false, v_msg);
  end if;

  insert into public.notifications (user_id, report_id, kind, message)
  select u.id, p_report, 'sla_warning',
         'The resident followed up on overdue complaint ' || v_report.tracking_id
         || coalesce(': ' || left(v_msg, 140), '.')
    from public.users u where u.role = 'admin';
end $$;


--
-- Name: guard_last_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_last_admin() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_left integer;
begin
  if old.role = 'admin'
     and (new.role <> 'admin' or new.is_suspended) then
    select count(*) into v_left from public.users
     where role = 'admin' and not is_suspended and id <> old.id;
    if v_left = 0 then
      raise exception
        'This is the last active administrator. Appoint another before removing this one.';
    end if;
  end if;
  return new;
end $$;


--
-- Name: FUNCTION guard_last_admin(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.guard_last_admin() IS 'Refuses any update that would leave Barangay 183 with no active administrator.';


--
-- Name: guard_privileged_user_fields(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_privileged_user_fields() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  -- auth.uid() is null only for service_role / backend contexts, which
  -- bypass RLS anyway; an unauthenticated client never reaches this row.
  if auth.uid() is null or public.is_admin() then
    return new;
  end if;

  -- The resident's own account deletion (request_account_deletion) scrubs
  -- these fields on purpose.
  if current_setting('smartsumbong.account_deletion', true) = 'on' and new.id = auth.uid() then
    return new;
  end if;

  if new.role                   is distinct from old.role
     or new.verification_status is distinct from old.verification_status
     or new.is_suspended        is distinct from old.is_suspended
     or new.verified_by         is distinct from old.verified_by
     or new.verified_at         is distinct from old.verified_at
     or new.rejection_reason    is distinct from old.rejection_reason then
    raise exception
      'Only an administrator may change account role, verification, or suspension state';
  end if;

  if new.mobile_number is distinct from old.mobile_number then
    raise exception
      'Your mobile number is how you sign in. Please ask the barangay to change it.';
  end if;

  if new.full_name is distinct from old.full_name then
    raise exception
      'Please ask the barangay to change the name on your account.';
  end if;

  return new;
end $$;


--
-- Name: FUNCTION guard_privileged_user_fields(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.guard_privileged_user_fields() IS 'Stops a resident editing fields that are not theirs to edit: role, verification and suspension (an admin''s), mobile_number (their login identity, derived in auth.users and only repairable with the service role) and full_name (what an admin compared against a government ID). Email remains theirs — it is contact-only since 0021.';


--
-- Name: hand_to_higher_official(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hand_to_higher_official(p_report uuid, p_official text, p_note text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_report   public.reports%rowtype;
  v_official text := nullif(trim(coalesce(p_official, '')), '');
  v_note     text := nullif(trim(coalesce(p_note, '')), '');
  v_cap      integer;
  v_used     integer;
  d          record;
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may hand a case to a higher official';
  end if;
  if v_official is null or char_length(v_official) < 2 or char_length(v_official) > 80 then
    raise exception 'Name the official (2 to 80 characters)';
  end if;
  if v_note is not null and char_length(v_note) > 300 then
    raise exception 'The note can be at most 300 characters';
  end if;

  select * into v_report from public.reports
   where id = p_report and deleted_at is null for update;
  if not found then
    raise exception 'No such report';
  end if;
  if v_report.status in ('pending_review', 'resolved', 'closed', 'archived', 'rejected', 'cancelled')
     or v_report.referred_to is not null then
    raise exception 'Only an open complaint can be handed to a higher official';
  end if;

  select max_deadline_extensions into v_cap from public.operational_settings where id = 1;
  v_cap  := coalesce(v_cap, 2);
  v_used := public.extensions_used(p_report);
  if v_used < v_cap then
    raise exception 'The target date can still be extended (% of % used). Hand the case up once the extensions run out.', v_used, v_cap;
  end if;

  -- Whoever is on it is stood down and told.
  for d in select id, tanod_id from public.dispatches
            where report_id = p_report and state in ('assigned', 'accepted') loop
    update public.dispatches
       set state = 'rerouted', rerouted_at = now(),
           reroute_reason = 'Handed to ' || v_official
     where id = d.id;
    insert into public.notifications (user_id, report_id, kind, message)
    values (d.tanod_id, p_report, 'reroute',
            v_report.tracking_id || ' was handed to ' || v_official || '. You no longer need to act on it.');
  end loop;

  update public.reports
     set higher_official      = v_official,
         higher_official_note = v_note,
         handed_up_at         = now(),
         status = case when status in ('validated', 'assigned') then 'in_progress'::report_status else status end
   where id = p_report;

  insert into public.status_logs (report_id, changed_by, old_status, new_status, remark)
  values (p_report, auth.uid(), v_report.status,
          case when v_report.status in ('validated', 'assigned') then 'in_progress'::report_status else v_report.status end,
          format('Handed to %s after the target date was extended %s time(s).', v_official, v_used)
          || coalesce(' ' || v_note, ''));

  insert into public.notifications (user_id, report_id, kind, message)
  values (v_report.resident_id, p_report, 'status_change',
          'Your complaint ' || v_report.tracking_id || ' is now handled by ' || v_official || '.'
          || coalesce(' ' || v_note, ''));
end $$;


--
-- Name: FUNCTION hand_to_higher_official(p_report uuid, p_official text, p_note text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.hand_to_higher_official(p_report uuid, p_official text, p_note text) IS 'Once a complaint''s extensions are used up (0079), the admin hands it to a barangay official: any tanod is stood down, the case stays open under that official, and a fresh extension allowance starts.';


--
-- Name: handle_new_auth_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_auth_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_full_name text := nullif(trim(new.raw_user_meta_data ->> 'full_name'), '');
  v_mobile    text := nullif(trim(new.raw_user_meta_data ->> 'mobile_number'), '');
  v_email     text := nullif(trim(new.raw_user_meta_data ->> 'contact_email'), '');
  v_role      text := coalesce(nullif(trim(new.raw_user_meta_data ->> 'role'), ''), 'resident');
  v_id_type   text := nullif(trim(new.raw_user_meta_data ->> 'id_type'), '');
  v_id_image  text := nullif(trim(new.raw_user_meta_data ->> 'id_image_url'), '');
  v_selfie    text := nullif(trim(new.raw_user_meta_data ->> 'selfie_url'), '');
  v_comma_pos int;
begin
  if current_setting('smartsumbong.provisioning_admin', true) = 'on' then
    return new;
  end if;

  if v_full_name is null then
    raise exception 'full_name is required at signup';
  end if;

  v_comma_pos := position(',' in v_full_name);
  if v_comma_pos <= 1
     or length(trim(substring(v_full_name from v_comma_pos + 1))) = 0 then
    raise exception 'full_name must be in the form Last Name, First Name';
  end if;

  if v_mobile is null then
    raise exception 'mobile_number is required at signup';
  end if;

  if v_mobile !~ '^\+639[0-9]{9}$' then
    raise exception 'mobile_number must be in the form +639XXXXXXXXX';
  end if;

  if new.email is distinct from public.auth_email_for(v_mobile) then
    raise exception 'auth identity does not match mobile_number';
  end if;

  if v_role not in ('resident', 'tanod') then
    raise exception 'role must be resident or tanod at signup';
  end if;

  if v_id_type is null then
    raise exception 'id_type is required at signup';
  end if;
  if not exists (select 1 from unnest(enum_range(null::id_document_type)) e
                  where e::text = v_id_type) then
    raise exception 'id_type % is not a recognised document type', v_id_type;
  end if;
  if v_id_image is null then
    raise exception 'id_image_url is required at signup';
  end if;
  if v_role = 'resident' and v_selfie is null then
    raise exception 'selfie_url is required at signup';
  end if;

  if v_email is not null and v_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then
    raise exception 'contact_email is not a valid address';
  end if;

  insert into public.users (
    id, full_name, email, mobile_number, role,
    id_type, id_image_url, selfie_url,
    verification_status, verification_submitted_at
  )
  values (
    new.id, v_full_name, v_email, v_mobile, v_role::user_role,
    v_id_type::id_document_type, v_id_image, v_selfie,
    'pending', now()
  );

  return new;
end $_$;


--
-- Name: FUNCTION handle_new_auth_user(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.handle_new_auth_user() IS 'Signup bridge. The auth address is synthetic and derived from mobile_number; contact_email is optional and arrives in metadata. Requires full_name (as "Last Name, First Name", 0032), mobile_number, id_type and id_image_url for every role; selfie_url is required for a resident but optional for a tanod (0036) — a tanod is matched to the barangay''s roster by an admin instead. Refuses any role other than resident or tanod. Runs in the same transaction as the auth.users insert, so a rejected application leaves no credential behind.';


--
-- Name: identity_media_in_use(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.identity_media_in_use(p_url text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (select 1 from public.users
                  where id_image_url = p_url or selfie_url = p_url or avatar_url = p_url)
      or exists (select 1 from public.profile_requests
                  where id_image_url = p_url and status <> 'declined')
$$;


