COMMENT ON FUNCTION public.is_barangay_media_url(p_url text) IS 'A delivery URL in the barangay''s Cloudinary cloud, folder barangay, UUIDv4 name, image extension. The pin for report_evidence (0079); mirrored by cloudinary_upload() in admin/includes/supabase.php.';


