--
-- Name: is_within_barangay(double precision, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_within_barangay(p_lat double precision, p_lon double precision) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select st_covers(b.geom, st_setsrid(st_makepoint(p_lon, p_lat), 4326)::geography)
    from public.barangay_boundary b where b.id = 1
$$;


--
-- Name: location_is_fresh(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.location_is_fresh(p_at timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select p_at is not null
     and p_at > now() - make_interval(mins => (
           select location_freshness_minutes from public.operational_settings where id = 1))
$$;


--
-- Name: log_duty_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_duty_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  -- Only an actual change, only for a tanod, never a null status.
  if new.role = 'tanod'
     and new.duty_status is not null
     and new.duty_status is distinct from old.duty_status then
    insert into public.attendance (tanod_id, duty_status)
    values (new.id, new.duty_status);
  end if;
  return new;
end $$;


--
-- Name: log_portal_error(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_portal_error(p_source text, p_page text, p_message text, p_detail text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_page text := left(coalesce(nullif(trim(p_page), ''), '?'), 200);
  v_msg  text := left(coalesce(nullif(trim(p_message), ''), '(no message)'), 500);
  v_sig  text;
begin
  if p_source not in ('server', 'browser') then return; end if;
  v_sig := md5(p_source || '|' || v_page || '|' || v_msg);
  insert into public.portal_errors (source, page, message, detail, signature)
  values (p_source, v_page, v_msg, left(p_detail, 2000), v_sig)
  on conflict (signature) do update
     set count = portal_errors.count + 1, last_seen = now(),
         detail = coalesce(excluded.detail, portal_errors.detail);
  -- Keep the table small: the 500 most recently seen.
  delete from public.portal_errors where id in (
    select id from public.portal_errors order by last_seen desc offset 500);
end $$;


--
-- Name: media_trash_done(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.media_trash_done(p_urls text[]) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  -- Also drops entries that came back into use: nothing to delete there.
  delete from public.media_trash t
   where t.url = any (p_urls)
      or public.identity_media_in_use(t.url);
$$;


--
-- Name: media_trash_due(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.media_trash_due(p_limit integer DEFAULT 100) RETURNS SETOF text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select t.url from public.media_trash t
   where t.queued_at < now() - interval '7 days'
     and not public.identity_media_in_use(t.url)
   order by t.queued_at
   limit p_limit
$$;


