--
-- Name: my_status_log_authors(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_status_log_authors(p_report_id uuid) RETURNS TABLE(status_log_id uuid, author_name text, is_system boolean, author_role text, resident_remark text)
    LANGUAGE sql STABLE SECURITY DEFINER
