$$;


--
-- Name: nearest_available_tanod(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nearest_available_tanod(p_report uuid) RETURNS TABLE(tanod_id uuid, full_name text, metres double precision)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select u.id, u.full_name,
         st_distance(u.last_geom, r.geom) as metres
    from public.reports r
    cross join lateral (
      select u.* from public.users u
       where u.is_dispatchable
         and (select count(*) from public.dispatches d
               where d.tanod_id = u.id and d.state in ('assigned', 'accepted')) < public.tanod_dispatch_cap()
         and not exists (
           select 1 from public.dispatches d
            where d.tanod_id = u.id and d.report_id = p_report)
    ) u
   where r.id = p_report
   order by public.location_is_fresh(u.last_location_at) desc,
            st_distance(u.last_geom, r.geom) nulls last,
            u.last_location_at desc nulls last
$$;


--
-- Name: FUNCTION nearest_available_tanod(p_report uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.nearest_available_tanod(p_report uuid) IS 'Tanods who can take this report, best first: a fresh location, then the nearest last known one, then on-duty tanods with none yet (0067).';


--
-- Name: otp_attempt(uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.otp_attempt(p_user uuid, p_purpose text, p_hash text, p_max integer DEFAULT 5) RETURNS TABLE(outcome text, attempts_left integer, otp_id uuid, new_mobile text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v public.password_otps%rowtype;
begin
  select * into v
    from public.password_otps o
   where o.user_id = p_user and o.purpose = p_purpose and o.used_at is null
   order by o.created_at desc
   limit 1
   for update;

  if not found or v.expires_at < now() or v.attempts >= p_max then
    return query select 'expired', 0, null::uuid, null::text;
    return;
  end if;

  if v.code_hash = p_hash then
    -- Marked used by the caller once the change it unlocks has gone through.
    return query select 'ok', p_max - v.attempts, v.id, v.new_mobile;
    return;
  end if;

  update public.password_otps set attempts = attempts + 1 where id = v.id;
  return query select 'wrong', greatest(0, p_max - v.attempts - 1), v.id, null::text;
end $$;


--
-- Name: FUNCTION otp_attempt(p_user uuid, p_purpose text, p_hash text, p_max integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.otp_attempt(p_user uuid, p_purpose text, p_hash text, p_max integer) IS '0107: checks one guess at the newest live SMS code, counting a wrong one under a row lock so parallel guesses cannot share a try. password-otp only.';


--
-- Name: ping_portal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ping_portal() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'net'
    AS $$
declare
  v_req   bigint;
  v_open  public.portal_outages;
  v_last2 boolean[];
begin
  -- File the answers that have arrived since the last run.
  update public.portal_uptime u
     set status = r.status_code,
         ok     = (r.status_code = 200 and not coalesce(r.timed_out, false)),
         error  = left(coalesce(r.error_msg, case when r.timed_out then 'timed out' end), 200)
    from net._http_response r
   where r.id = u.request_id and u.ok is null;
  update public.portal_uptime set ok = false, error = 'no answer'
   where ok is null and checked_at < now() - interval '15 minutes';
  delete from public.portal_uptime where checked_at < now() - interval '30 days';

  -- Two misses in a row open an outage (and alert); an answer closes it.
  select array_agg(ok order by checked_at desc) into v_last2
    from (select ok, checked_at from public.portal_uptime where ok is not null order by checked_at desc limit 2) x;
  select * into v_open from public.portal_outages where ended_at is null order by started_at desc limit 1;
  if v_open.id is null and v_last2 = array[false, false] then
    insert into public.portal_outages (started_at)
    select min(checked_at) from (select checked_at from public.portal_uptime where ok is not null order by checked_at desc limit 2) y;
    perform public._notify_admins('The admin portal stopped answering at '
      || to_char(now() at time zone 'Asia/Manila', 'HH12:MI AM') || '. It is checked every 10 minutes; you will be told when it is back.');
  elsif v_open.id is not null and coalesce(v_last2[1], false) then
    update public.portal_outages set ended_at = now() where id = v_open.id;
    perform public._notify_admins('The admin portal is answering again. It was down for about '
      || greatest(1, round(extract(epoch from now() - v_open.started_at) / 60))::int || ' minutes.');
  end if;

  select net.http_get('https://smartsumbong-ph.onrender.com/admin/ping.php', timeout_milliseconds := 60000) into v_req;
  insert into public.portal_uptime (request_id) values (v_req);
end $$;


--
-- Name: portal_uptime_summary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_uptime_summary() RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public.is_admin() then raise exception 'Only an administrator may see the uptime record'; end if;
  return json_build_object(
    'day_checks',  (select count(*) from portal_uptime where ok is not null and checked_at > now() - interval '1 day'),
    'day_ok',      (select count(*) from portal_uptime where ok and checked_at > now() - interval '1 day'),
    'week_checks', (select count(*) from portal_uptime where ok is not null and checked_at > now() - interval '7 days'),
    'week_ok',     (select count(*) from portal_uptime where ok and checked_at > now() - interval '7 days'),
    'last_at',     (select checked_at from portal_uptime where ok is not null order by checked_at desc limit 1),
    'last_ok',     (select ok from portal_uptime where ok is not null order by checked_at desc limit 1)
  );
end $$;


--
-- Name: post_dispatch_update(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_dispatch_update(p_dispatch uuid, p_body text, p_media jsonb DEFAULT '[]'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_d     public.dispatches%rowtype;
  v_admin boolean := public.is_admin();
  v_body  text := nullif(trim(coalesce(p_body, '')), '');
  v_id    uuid;
  v_tick  text;
  m       jsonb;
begin
  select * into v_d from public.dispatches where id = p_dispatch;
  if not found then
    raise exception 'Dispatch not found';
  end if;

  if v_admin then
    if v_d.state not in ('assigned', 'accepted') then
      raise exception 'This dispatch is closed';
    end if;
  elsif v_d.tanod_id is distinct from auth.uid() or v_d.state <> 'accepted' then
    raise exception 'Dispatch not found, not yours, or not accepted';
  end if;

  if v_body is null and jsonb_array_length(coalesce(p_media, '[]'::jsonb)) = 0 then
    raise exception 'An update needs a message or a photo';
  end if;
  if jsonb_array_length(coalesce(p_media, '[]'::jsonb)) > 6 then
    raise exception 'Up to 6 attachments per update';
  end if;

  insert into public.dispatch_updates (dispatch_id, author_id, kind, body)
  values (p_dispatch, auth.uid(), 'note', v_body)
  returning id into v_id;

  for m in select * from jsonb_array_elements(coalesce(p_media, '[]'::jsonb)) loop
    insert into public.dispatch_media (dispatch_id, update_id, media_url, mime_type, bytes)
    values (p_dispatch, v_id, m->>'media_url', m->>'mime_type', (m->>'bytes')::integer);
  end loop;

  if v_admin and v_d.tanod_id is not null then
    select tracking_id into v_tick from public.reports where id = v_d.report_id;
    insert into public.notifications (user_id, report_id, kind, message)
    values (v_d.tanod_id, v_d.report_id, 'status_change'::notification_kind,
            'Barangay on ' || coalesce(v_tick, 'your dispatch') || ': '
            || coalesce(left(v_body, 140), 'sent a photo'));
  end if;

  return v_id;
end $$;


--
-- Name: post_report_message(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_report_message(p_report uuid, p_body text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_report public.reports%rowtype;
  v_admin  boolean := public.is_admin();
  v_body   text := nullif(trim(coalesce(p_body, '')), '');
  v_id     uuid;
begin
  if v_body is null then
    raise exception 'Write a message first';
  end if;
  if char_length(v_body) > 1000 then
    raise exception 'Keep the message under 1000 characters';
  end if;

  select * into v_report from public.reports
   where id = p_report and deleted_at is null;
  if not found or (not v_admin and v_report.resident_id is distinct from auth.uid()) then
    raise exception 'Complaint not found';
  end if;

  insert into public.report_messages (report_id, author_id, from_barangay, body)
  values (p_report, auth.uid(), v_admin, v_body)
  returning id into v_id;

  if v_admin then
    insert into public.notifications (user_id, report_id, kind, message)
    values (v_report.resident_id, p_report, 'status_change',
            'The barangay replied about ' || v_report.tracking_id || ': ' || left(v_body, 140));
  else
    insert into public.notifications (user_id, report_id, kind, message)
    select u.id, p_report, 'status_change',
           'A resident asked about ' || v_report.tracking_id || ': ' || left(v_body, 140)
      from public.users u where u.role = 'admin';
  end if;

  return v_id;
end $$;


--
-- Name: profile_requests_queue_media_trash(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.profile_requests_queue_media_trash() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'DELETE' then
    perform public.queue_media_trash(old.id_image_url);
    return old;
  end if;
  if new.status = 'declined' and old.status <> 'declined' then
    perform public.queue_media_trash(new.id_image_url);
  end if;
  return new;
end $$;


--
-- Name: promote_to_admin(uuid, text, integer, public.user_role); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.promote_to_admin(p_user uuid, p_reason text DEFAULT NULL::text, p_handover_days integer DEFAULT NULL::integer, p_revert_role public.user_role DEFAULT NULL::public.user_role) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_user   public.users%rowtype;
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may appoint another administrator';
  end if;

  select * into v_user from public.users where id = p_user for update;
  if not found then
    raise exception 'No such account';
  end if;

  if v_user.role = 'admin' then
    raise exception '% is already an administrator', public.display_name(v_user.full_name);
  end if;

  if v_user.verification_status <> 'verified' then
    raise exception
      '% is not a verified account. Only a verified resident or tanod of Barangay 183 may be appointed.',
      public.display_name(v_user.full_name);
  end if;

  if v_user.is_suspended then
    raise exception '% is suspended and cannot be appointed', public.display_name(v_user.full_name);
  end if;

  if p_handover_days is not null then
    if p_handover_days < 1 or p_handover_days > 90 then
      raise exception 'A handover window must be between 1 and 90 days';
    end if;
    if p_revert_role is null or p_revert_role = 'admin' then
      raise exception 'Choose the role you will return to when the handover ends';
    end if;
  end if;

  -- A tanod who becomes an admin stops being dispatchable: they are no
  -- longer on the roster, and leaving them in it would send incidents to
  -- someone sitting at a desk. sync_dispatchable does this on its own
  -- once the role changes, but the duty status is cleared here so the
  -- Personnel screen does not still show them as On Duty.
  update public.users
     set role        = 'admin',
         duty_status = null
   where id = p_user;

  if p_handover_days is not null then
    update public.users
       set admin_handover_until        = now() + (p_handover_days || ' days')::interval,
           admin_handover_role         = p_revert_role,
           admin_handover_successor_id = p_user
     where id = auth.uid();
  end if;

  insert into public.account_audit (subject_id, actor_id, action, detail)
  values (p_user, auth.uid(), 'promoted_to_admin',
          coalesce(v_reason, format('Appointed by %s',
            (select public.display_name(full_name) from public.users where id = auth.uid()))));

  if p_handover_days is not null then
    insert into public.account_audit (subject_id, actor_id, action, detail)
    values (auth.uid(), auth.uid(), 'handover_scheduled',
            format('Training %s for up to %s day(s); returns to %s on %s',
              public.display_name(v_user.full_name), p_handover_days, p_revert_role,
              to_char(now() + (p_handover_days || ' days')::interval, 'Mon dd, yyyy')));
  end if;

  insert into public.notifications (user_id, kind, message)
  values (p_user, 'verification',
          'You have been given barangay administrator access to Smart Sumbong.'
          || case when p_handover_days is not null
               then format(' The outgoing administrator will continue to help for up to %s day(s).', p_handover_days)
               else '' end);

  return public.display_name(v_user.full_name);
end $$;


--
-- Name: FUNCTION promote_to_admin(p_user uuid, p_reason text, p_handover_days integer, p_revert_role public.user_role); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.promote_to_admin(p_user uuid, p_reason text, p_handover_days integer, p_revert_role public.user_role) IS 'Grants admin access. p_handover_days/p_revert_role (0055) are both optional -- when given, also schedules the CALLING admin''s own return to p_revert_role once p_handover_days elapse (max 90).';


--
-- Name: public_incidents(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.public_incidents() RETURNS TABLE(id uuid, category public.complaint_category, status public.report_status, latitude double precision, longitude double precision, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  select r.id, r.category, r.status, r.latitude, r.longitude, r.created_at
    from public.reports r
   where r.is_public
     and r.deleted_at is null
     and r.status not in ('rejected', 'cancelled')
     and auth.uid() is not null
   order by r.created_at desc
   limit 500
$$;


--
-- Name: purge_old_notifications(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_old_notifications() RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  delete from public.notifications
   where (is_read and created_at < now() - interval '90 days')
      or created_at < now() - interval '365 days';
$$;


--
-- Name: FUNCTION purge_old_notifications(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.purge_old_notifications() IS '0108: daily. Read notifications go after 90 days, any after a year.';


--
-- Name: queue_media_trash(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.queue_media_trash(p_url text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  insert into public.media_trash (url)
  select p_url
   where p_url is not null and public.is_identity_media_url(p_url)
  on conflict (url) do update set queued_at = now();
$$;


--
-- Name: redispatch_report(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.redispatch_report(p_report uuid, p_why text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_attempts smallint;
  v_max      smallint;
  v_next     uuid;
begin
  select max_dispatch_attempts into v_max from public.operational_settings where id = 1;

  update public.reports
     set dispatch_attempts = dispatch_attempts + 1,
         status = 'validated'
   where id = p_report
  returning dispatch_attempts into v_attempts;

  if v_attempts > v_max then
    update public.reports
       set escalation_level = greatest(escalation_level, 1),
           escalated_at = coalesce(escalated_at, now())
     where id = p_report;

    insert into public.status_logs (report_id, changed_by, old_status, new_status,
                                    remark, is_system)
    select p_report, r.resident_id, 'validated', 'validated',
           format('Automatic dispatch gave up after %s offers (%s) — manual assignment required',
                  v_attempts, p_why), true
      from public.reports r where r.id = p_report;

    insert into public.notifications (user_id, report_id, kind, message)
    select id, p_report, 'escalation',
           'A report could not be dispatched automatically and needs manual assignment.'
      from public.users where role = 'admin';
    return null;
  end if;

  insert into public.status_logs (report_id, changed_by, old_status, new_status,
                                  remark, is_system)
  select p_report, r.resident_id, 'assigned', 'validated',
         format('Re-dispatching: %s (offer %s of %s)', p_why, v_attempts, v_max), true
    from public.reports r where r.id = p_report;

  select public.auto_dispatch(p_report) into v_next;
  return v_next;
end $$;


--
-- Name: refer_report(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refer_report(p_report uuid, p_agency text, p_note text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_report public.reports%rowtype;
  v_agency text := nullif(trim(coalesce(p_agency, '')), '');
  v_note   text := nullif(trim(coalesce(p_note, '')), '');
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may escalate a complaint';
  end if;
  if v_agency is null then
    raise exception 'Choose the office the complaint is escalated to';
  end if;

  select * into v_report from public.reports
   where id = p_report and deleted_at is null for update;
  if not found then
    raise exception 'No such report';
  end if;
  if v_report.referred_to is not null then
    raise exception 'This complaint was already escalated to %', v_report.referred_to;
  end if;
  if v_report.status in ('closed', 'archived', 'rejected', 'cancelled') then
    raise exception 'This complaint is already closed';
  end if;

  update public.dispatches
     set state = 'rerouted', rerouted_at = now(),
         reroute_reason = 'Escalated to ' || v_agency
   where report_id = p_report and state in ('assigned', 'accepted');

  update public.reports
     set status        = 'closed',
         closed_at     = now(),
         referred_to   = v_agency,
         referral_note = v_note,
         referred_at   = now(),
         referred_by   = auth.uid()
   where id = p_report;

  -- Any request still waiting on this complaint is settled by this.
  update public.escalation_requests
     set status = 'approved', decided_by = auth.uid(), decided_at = now(),
         decided_office = v_agency
   where report_id = p_report and status = 'pending';

  insert into public.status_logs (report_id, changed_by, old_status, new_status, remark)
  values (p_report, auth.uid(), v_report.status, 'closed',
          'Escalated to ' || v_agency || coalesce(': ' || v_note, '.'));

  insert into public.notifications (user_id, report_id, kind, message)
  values (v_report.resident_id, p_report, 'status_change',
          format('Your complaint %s has been escalated to the %s, which handles this kind of case.%s',
                 v_report.tracking_id, v_agency,
                 coalesce(' Note from the barangay: ' || v_note, '')));
end $$;


--
-- Name: refuse_audit_write(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refuse_audit_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  if tg_op = 'UPDATE' then
    raise exception 'The audit trail cannot be edited. Add a correcting entry instead.';
  end if;

  -- Branch on the table before touching a column, because PL/pgSQL
  -- evaluates the whole condition and account_audit has no report_id.
  if tg_table_name = 'account_audit' then
    raise exception 'Account audit entries cannot be deleted.';
  end if;

  -- A DELETE on a complaint trail is only legitimate as a cascade from a
  -- report that has already gone. If the parent is still there, someone
  -- is removing a single entry — exactly what this guards against.
  if exists (select 1 from public.reports where id = old.report_id) then
    raise exception 'Audit entries cannot be deleted while the complaint exists.';
  end if;

  return old;
end $$;


--
-- Name: register_device_token(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.register_device_token(p_token text, p_platform text DEFAULT 'android'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'Not signed in';
  end if;
  if p_token is null or char_length(trim(p_token)) = 0 then
    raise exception 'A device token is required';
  end if;

  insert into public.device_tokens (user_id, fcm_token, platform)
  values (auth.uid(), trim(p_token), coalesce(nullif(trim(p_platform), ''), 'android'))
  on conflict (user_id, fcm_token)
  do update set updated_at = now(), platform = excluded.platform;
end $$;


--
-- Name: register_login_failure(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.register_login_failure(p_mobile text) RETURNS TABLE(locked boolean, seconds_remaining integer, attempts_remaining integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
declare
  v_now    timestamptz := now();
  v_source text := public.request_source();
  v_hits   integer;
  v_count  integer;
  v_locked timestamptz;
begin
  if p_mobile is null or p_mobile !~ '^\+63[0-9]{10}$' then
    return query select false, 0, 5;
    return;
  end if;

  if v_source is not null then
    insert into public.login_failure_sources as s (source, window_start, hits)
    values (v_source, v_now, 1)
    on conflict (source) do update
       set hits = case when s.window_start < v_now - interval '15 minutes' then 1 else s.hits + 1 end,
           window_start = case when s.window_start < v_now - interval '15 minutes' then v_now else s.window_start end
    returning hits into v_hits;

    if v_hits > 20 then
      return query select false, 0, 5;
      return;
    end if;

    -- Keep the table to the addresses seen today.
    if v_hits = 1 then
      delete from public.login_failure_sources where window_start < v_now - interval '1 day';
    end if;
  end if;

  -- Unchanged from 0031 from here on.
  insert into public.login_attempts (mobile_number, failed_count, locked_until, last_attempt_at)
  values (p_mobile, 1, null, v_now)
  on conflict (mobile_number) do update
     set failed_count = case
           when login_attempts.locked_until is not null
                and login_attempts.locked_until <= v_now
           then 1
           else login_attempts.failed_count + 1
         end,
         locked_until = case
           when (case
                   when login_attempts.locked_until is not null
                        and login_attempts.locked_until <= v_now
                   then 1
                   else login_attempts.failed_count + 1
                 end) >= 5
           then v_now + interval '30 minutes'
           else null
         end,
         last_attempt_at = v_now
  returning failed_count, locked_until
    into v_count, v_locked;

  if v_count >= 5 then
    return query select true,
      greatest(0, ceil(extract(epoch from (v_locked - v_now)))::int),
      0;
  else
    return query select false, 0, greatest(0, 5 - v_count);
  end if;
end $_$;


--
-- Name: FUNCTION register_login_failure(p_mobile text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.register_login_failure(p_mobile text) IS 'Call after GoTrue rejects a password for this number — never for not-confirmed, suspended, or rate-limited responses, which are not a guessed password. Returns whether this attempt just triggered the 30-minute lock, and how many attempts remain if not.';


--
-- Name: reject_resolution(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_resolution(p_report uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_report public.reports%rowtype;
  v_d      public.dispatches%rowtype;
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may return a resolution';
  end if;
  if v_reason is null then
    raise exception 'Say what the tanod still needs to do';
  end if;
  select * into v_report from public.reports
   where id = p_report and deleted_at is null for update;
  if not found or v_report.resolution_submitted_at is null then
    raise exception 'There is no resolution waiting for approval';
  end if;

  select * into v_d from public.dispatches
   where report_id = p_report and state = 'resolved'
   order by resolved_at desc nulls last limit 1;

  -- Back to the tanod: their dispatch is open again.
  if v_d.id is not null then
    update public.dispatches set state = 'accepted', resolved_at = null where id = v_d.id;
    insert into public.dispatch_updates (dispatch_id, author_id, kind, body)
    values (v_d.id, auth.uid(), 'note', 'Resolution returned: ' || v_reason);
    insert into public.notifications (user_id, report_id, kind, message)
    values (v_d.tanod_id, p_report, 'status_change',
            'The barangay returned your resolution of ' || v_report.tracking_id || ': ' || left(v_reason, 140));
  end if;

  update public.reports
     set status = 'in_progress', resolution_submitted_at = null,
         resolution_returned_reason = v_reason
   where id = p_report;

  insert into public.status_logs (report_id, changed_by, old_status, new_status, remark)
  values (p_report, auth.uid(), v_report.status, 'in_progress',
          'Resolution returned to the tanod: ' || v_reason);
end $$;


--
-- Name: release_case(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_case(p_report uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_h uuid;
begin
  if not public.is_admin() then raise exception 'Only an administrator may release a case'; end if;
  select handler_id into v_h from public.reports where id = p_report and deleted_at is null for update;
  if not found then raise exception 'No such report'; end if;
  if v_h is distinct from auth.uid() then raise exception 'Only the handler can release this case'; end if;
  perform set_config('smartsumbong.handler_change', 'on', true);
  update public.reports set handler_id = null, handled_since = null where id = p_report;
  perform set_config('smartsumbong.handler_change', 'off', true);
  insert into public.case_handler_log (report_id, admin_id, action) values (p_report, auth.uid(), 'release');
end $$;


--
-- Name: reopen_report(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reopen_report(p_report uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_old report_status;
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may reopen a complaint';
  end if;

  select status into v_old from public.reports where id = p_report;

  -- 0071: the old 24-hour window is gone; the admin sets a new date
  -- when assigning again.
  update public.reports
     set status = 'validated',
         reopened_count = reopened_count + 1,
         resolved_at = null,
         due_at = null
   where id = p_report and status in ('resolved', 'closed');

  if not found then
    raise exception 'Report is not in a reopenable state';
  end if;

  insert into public.status_logs (report_id, changed_by, old_status, new_status, remark)
  values (p_report, auth.uid(), v_old, 'validated', 'Reopened: ' || p_reason);
end $$;


--
-- Name: report_hotspots(timestamp with time zone, timestamp with time zone, public.complaint_category); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_hotspots(p_from timestamp with time zone, p_to timestamp with time zone, p_category public.complaint_category DEFAULT NULL::public.complaint_category) RETURNS TABLE(cluster_id integer, centroid_lat double precision, centroid_lng double precision, report_count integer, top_category public.complaint_category, first_at timestamp with time zone, last_at timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  with scoped as (
    select r.category, r.created_at,
           st_transform(r.geom::geometry, 3857) as g3857
      from public.reports r
     where r.deleted_at is null
       and r.created_at >= p_from
       and r.created_at <  p_to
       and (p_category is null or r.category = p_category)
  ),
  clustered as (
    select *,
           st_clusterdbscan(g3857, eps := 45, minpoints := 3) over () as cid
      from scoped
  )
  select
    cid,
    st_y(st_transform(st_centroid(st_collect(g3857)), 4326)),
    st_x(st_transform(st_centroid(st_collect(g3857)), 4326)),
    count(*)::integer,
    mode() within group (order by category),
    min(created_at),
    max(created_at)
    from clustered
   where cid is not null   -- DBSCAN "noise": no cluster, not a hotspot
   group by cid
   order by count(*) desc
$$;


--
-- Name: FUNCTION report_hotspots(p_from timestamp with time zone, p_to timestamp with time zone, p_category public.complaint_category); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.report_hotspots(p_from timestamp with time zone, p_to timestamp with time zone, p_category public.complaint_category) IS 'Real spatial clustering (PostGIS ST_ClusterDBSCAN, 45m/3pts) over reports in a window, ranked by size. RLS-scoped like dashboard_metrics -- an admin sees barangay-wide hotspots, anyone else only ever clusters what reports_resident_read already lets them see.';


--
-- Name: request_account_deletion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_account_deletion() RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_uid         uuid := auth.uid();
  v_role        user_role;
  v_has_reports boolean;
  v_scrub_email text;
  v_scrub_phone text;
begin
  if v_uid is null then
    raise exception 'Not signed in';
  end if;
  -- 0089: the scrub below changes the name and number, which
  -- guard_privileged_user_fields refuses a resident; this call is allowed.
  perform set_config('smartsumbong.account_deletion', 'on', true);

  select role into v_role from public.users where id = v_uid;
  if v_role is null then
    raise exception 'No such account';
  end if;
  if v_role <> 'resident' then
    raise exception 'Self-service account deletion is currently only available to resident accounts';
  end if;

  -- 0090: an account-change audit entry (every verified account has one)
  -- pins the row just like a filed complaint does, so it is kept and
  -- scrubbed too; a hard delete would be refused by account_audit.
  select exists(select 1 from public.reports where resident_id = v_uid)
      or exists(select 1 from public.account_audit where subject_id = v_uid or actor_id = v_uid)
    into v_has_reports;

  if not v_has_reports then
    -- Nothing else in this schema references this account. The caller
    -- hard-deletes auth.users, which cascades everywhere on its own.
    return true;
  end if;

  -- Unique placeholders, not a shared literal â€” public.users.email and
  -- .mobile_number are both `unique`, and a second resident deleting
  -- their account the same day must not collide with the first.
  v_scrub_email := 'deleted+' || replace(v_uid::text, '-', '') || '@smartsumbong.invalid';
  v_scrub_phone := 'deleted-' || left(replace(v_uid::text, '-', ''), 10);

  update public.users
     set full_name        = 'Deleted Resident',
         email             = v_scrub_email,
         mobile_number     = v_scrub_phone,
         id_image_url      = null,
         selfie_url        = null,
         address           = null,
         avatar_url        = null,
         rejection_reason  = null,
         is_suspended      = true,
         suspended_reason  = 'Account deleted by the resident. Their filed reports remain on record.'
   where id = v_uid;

  delete from public.device_tokens where user_id = v_uid;

  return false;
end $$;


--
-- Name: FUNCTION request_account_deletion(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.request_account_deletion() IS 'Self-service account deletion, resident-only, called by the delete-account Edge Function as the resident''s own session. Returns true when it is safe for the caller to hard-delete auth.users (no reports on file), false when it has instead scrubbed public.users in place and the caller should ban the auth user -- reports are never destroyed, same philosophy as reports.deleted_at.';


--
-- Name: request_additional_details(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_additional_details(p_report uuid, p_message text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_status  report_status;
  v_owner   uuid;
  v_ticket  text;
  v_message text := nullif(trim(p_message), '');
  v_id      uuid;
begin
  if v_message is null then
    raise exception 'Please say what details you need';
  end if;
  if char_length(v_message) > 300 then
    raise exception 'Keep the request under 300 characters';
  end if;

  select status, resident_id, tracking_id
    into v_status, v_owner, v_ticket
    from public.reports
   where id = p_report and deleted_at is null;

  if v_status is null then
    raise exception 'Report not found';
  end if;

  if not (public.is_admin()
          or exists (select 1 from public.dispatches d
                      where d.report_id = p_report
                        and d.tanod_id = auth.uid()
                        and d.state = 'accepted')) then
    raise exception 'Only the tanod handling this report can ask for more details';
  end if;

  if v_status not in ('assigned', 'in_progress', 'offline_investigation') then
    raise exception 'More details can only be asked for while the report is being worked on';
  end if;

  if exists (select 1 from public.detail_requests
              where report_id = p_report and responded_at is null) then
    raise exception 'There is already a request for more details waiting on the resident';
  end if;

  insert into public.detail_requests (report_id, requested_by, message)
  values (p_report, auth.uid(), v_message)
  returning id into v_id;

  insert into public.status_logs
    (report_id, changed_by, old_status, new_status, remark)
  values
    (p_report, auth.uid(), v_status, v_status,
     'More details requested: ' || v_message);

  insert into public.notifications (user_id, report_id, kind, message)
  values (v_owner, p_report, 'status_change'::notification_kind,
          'More details needed for ' || v_ticket || ': ' || v_message);

  return v_id;
end $$;


--
-- Name: FUNCTION request_additional_details(p_report uuid, p_message text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.request_additional_details(p_report uuid, p_message text) IS 'The accepted tanod (or an admin) asks the resident for more details on a report being worked on. One open request per report. Logs to status_logs and notifies the resident. 0065.';


--
-- Name: request_appeal(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_appeal(p_report uuid, p_reason text, p_media jsonb DEFAULT '[]'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_status report_status;
  v_owner  uuid;
  v_ticket text;
  v_item   jsonb;
begin
  if nullif(trim(p_reason), '') is null then
    raise exception 'Please explain why this rejection should be reviewed again';
  end if;

  if jsonb_typeof(coalesce(p_media, '[]'::jsonb)) <> 'array' then
    raise exception 'p_media must be a JSON array of {media_url, mime_type, bytes}'
      using errcode = 'invalid_parameter_value';
  end if;

  select status, resident_id, tracking_id
    into v_status, v_owner, v_ticket
    from public.reports
   where id = p_report and deleted_at is null;

  if v_status is null then
    raise exception 'Report not found';
  end if;
  if v_owner is distinct from auth.uid() then
    raise exception 'Only the resident who filed a report may appeal it';
  end if;
  if v_status <> 'rejected' then
    raise exception 'Only a rejected complaint can be appealed';
  end if;

  -- The request is a notification, not a status change. An admin acts on
  -- it with appeal_report(), which is where due_at and appealed_at live
  -- — the same split request_reopen()/reopen_report() already use.
  insert into public.notifications (user_id, kind, message)
  select a.id, 'status_change',
         'Appeal requested for ' || v_ticket || ': ' || trim(p_reason)
    from public.users a
   where a.role = 'admin'
     and not a.is_suspended;

  insert into public.status_logs
    (report_id, changed_by, old_status, new_status, remark)
  values
    (p_report, auth.uid(), v_status, v_status,
     'Resident appealed the rejection: ' || trim(p_reason));

  -- Same insert idiom as request_reopen() (0037) — report_media_insert
  -- and report_media_url_pinned still apply; SECURITY DEFINER bypasses
  -- RLS the same way the rest of this function already does, so the
  -- ownership check above is what makes this safe, not the policy.
  for v_item in select value from jsonb_array_elements(coalesce(p_media, '[]'::jsonb))
  loop
    insert into public.report_media (report_id, media_url, mime_type, bytes)
    values (p_report,
            v_item ->> 'media_url',
            v_item ->> 'mime_type',
            (v_item ->> 'bytes')::integer);
  end loop;
end $$;


--
-- Name: FUNCTION request_appeal(p_report uuid, p_reason text, p_media jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.request_appeal(p_report uuid, p_reason text, p_media jsonb) IS 'The resident disputes a denial; the barangay decides. Notifies admins, writes the request to status_logs, and optionally attaches evidence to report_media, without changing the report''s status. SECURITY DEFINER for the same reason as request_reopen.';


--
-- Name: request_escalation(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_escalation(p_dispatch uuid, p_reason text, p_office text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_d      public.dispatches%rowtype;
  v_tick   text;
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
  v_id     uuid;
begin
  select * into v_d from public.dispatches
   where id = p_dispatch and tanod_id = auth.uid() and state = 'accepted';
  if not found then
    raise exception 'Dispatch not found, not yours, or not accepted';
  end if;
  if v_reason is null then
    raise exception 'Say why this needs to go beyond the barangay';
  end if;
  if exists (select 1 from public.escalation_requests
              where report_id = v_d.report_id and status = 'pending') then
    raise exception 'An escalation request for this complaint is already waiting';
  end if;

  insert into public.escalation_requests (report_id, dispatch_id, requested_by, reason, suggested_office)
  values (v_d.report_id, p_dispatch, auth.uid(), v_reason, nullif(trim(coalesce(p_office, '')), ''))
  returning id into v_id;

  select tracking_id into v_tick from public.reports where id = v_d.report_id;

  insert into public.dispatch_updates (dispatch_id, author_id, kind, body)
  values (p_dispatch, auth.uid(), 'note', 'Escalation requested: ' || v_reason);

  insert into public.notifications (user_id, report_id, kind, message)
  select u.id, v_d.report_id, 'escalation',
         'Escalation requested for ' || v_tick || ': ' || left(v_reason, 140)
    from public.users u where u.role = 'admin';

  return v_id;
end $$;


--
-- Name: request_id_reupload(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_id_reupload(p_id_type text, p_id_image_url text, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_name text;
begin
  select full_name into v_name from public.users where id = auth.uid() and role in ('resident', 'tanod');
  if v_name is null then
    raise exception 'Only a resident or tanod account can send an ID';
  end if;
  if not exists (select 1 from unnest(enum_range(null::id_document_type)) e where e::text = p_id_type) then
    raise exception 'Choose the type of ID';
  end if;
  if p_id_image_url is null or not public.is_media_url(p_id_image_url) or p_id_image_url !~ '/ids/' then
    raise exception 'The ID photo did not upload correctly. Try again.';
  end if;
  if exists (select 1 from public.profile_requests where user_id = auth.uid() and kind = 'id_document' and status = 'pending') then
    raise exception 'You already have an ID waiting for the barangay';
  end if;

  insert into public.profile_requests (user_id, kind, id_type, id_image_url, reason)
  values (auth.uid(), 'id_document', p_id_type::id_document_type, p_id_image_url, nullif(trim(coalesce(p_reason, '')), ''));
  perform public._notify_admins(public.display_name(v_name) || ' sent a new photo of their ID.', auth.uid());
end $$;


--
-- Name: request_ocr_rescan(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_ocr_rescan(p_user uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_user public.users%rowtype;
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may request an ID re-check';
  end if;

  select * into v_user from public.users where id = p_user for update;
  if not found then
    raise exception 'No such account';
  end if;

  if v_user.id_image_url is null then
    raise exception 'This account has no ID photo on file to re-check';
  end if;

  update public.users
     set ocr_rescan_requested_at = now()
   where id = p_user;

  insert into public.notifications (user_id, kind, message)
  values (p_user, 'status_change',
    'The barangay asked to re-check your uploaded ID. Open the app to complete it.');
end $$;


--
-- Name: FUNCTION request_ocr_rescan(p_user uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.request_ocr_rescan(p_user uuid) IS 'Admin-only. Flags an account for the resident''s own app to silently re-run on-device OCR against its already-uploaded ID photo next time it opens. Does not run OCR itself -- there is no server-side OCR in this project, see 0039''s header.';


--
-- Name: request_profile_change(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_profile_change(p_field text, p_value text, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
declare
  v_name   text;
  v_value  text := trim(coalesce(p_value, ''));
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
  v_comma  int;
begin
  select full_name into v_name from public.users where id = auth.uid();
  if v_name is null then
    raise exception 'Not signed in';
  end if;
  if p_field not in ('mobile_number', 'full_name') then
    raise exception 'Only a name or mobile number change can be requested';
  end if;

  if p_field = 'mobile_number' then
    if v_value !~ '^\+639[0-9]{9}$' then
      raise exception 'Enter the mobile number as 09XXXXXXXXX';
    end if;
    perform public._notify_admins(public.display_name(v_name) || ' asked to change their mobile number to ' || v_value
                                  || coalesce(' — ' || v_reason, '') || '. Changing a number is done at the counter.', auth.uid());
    return;
  end if;

  v_comma := position(',' in v_value);
  if v_comma <= 1 or length(trim(substring(v_value from v_comma + 1))) = 0 then
    raise exception 'Enter both a first name and a last name';
  end if;
  if exists (select 1 from public.profile_requests where user_id = auth.uid() and kind = 'full_name' and status = 'pending') then
    raise exception 'You already have a name change waiting for the barangay';
  end if;

  insert into public.profile_requests (user_id, kind, new_full_name, reason)
  values (auth.uid(), 'full_name', v_value, v_reason);
  perform public._notify_admins(public.display_name(v_name) || ' asked to change their name to ' || public.display_name(v_value)
                                || coalesce(' — ' || v_reason, '') || '.', auth.uid());
end $_$;


--
-- Name: FUNCTION request_profile_change(p_field text, p_value text, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.request_profile_change(p_field text, p_value text, p_reason text) IS 'Notifies admins that a resident wants their number or name changed. Changes nothing: both fields require a person to check an ID, and mobile_number additionally requires a service-role update to auth.users that no client should be able to make.';


--
-- Name: request_reopen(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_reopen(p_report uuid, p_reason text, p_media jsonb DEFAULT '[]'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_status  report_status;
  v_owner   uuid;
  v_ticket  text;
  v_item    jsonb;
begin
  if nullif(trim(p_reason), '') is null then
    raise exception 'Please say why this report should be reopened';
  end if;

  if jsonb_typeof(coalesce(p_media, '[]'::jsonb)) <> 'array' then
    raise exception 'p_media must be a JSON array of {media_url, mime_type, bytes}'
      using errcode = 'invalid_parameter_value';
  end if;

  select status, resident_id, tracking_id
    into v_status, v_owner, v_ticket
    from public.reports
   where id = p_report and deleted_at is null;

  if v_status is null then
    raise exception 'Report not found';
  end if;
  if v_owner is distinct from auth.uid() then
    raise exception 'Only the resident who filed a report may ask to reopen it';
  end if;
  if v_status not in ('resolved', 'closed') then
    raise exception 'Only a finished report can be reopened';
  end if;

  -- The request is a notification, not a status change. An admin acts on
  -- it with reopen_report(), which is where the SLA clock and the
  -- reopened_count live.
  insert into public.notifications (user_id, kind, message)
  select a.id, 'status_change',
         'Reopen requested for ' || v_ticket || ': ' || trim(p_reason)
    from public.users a
   where a.role = 'admin'
     and not a.is_suspended;

  insert into public.status_logs
    (report_id, changed_by, old_status, new_status, remark)
  values
    (p_report, auth.uid(), v_status, v_status,
     'Resident requested reopening: ' || trim(p_reason));

  -- Same insert idiom as file_report() (0017) — report_media_insert
  -- and report_media_url_pinned still apply; SECURITY DEFINER bypasses
  -- RLS the same way the rest of this function already does, so the
  -- ownership check above is what makes this safe, not the policy.
  for v_item in select value from jsonb_array_elements(coalesce(p_media, '[]'::jsonb))
  loop
    insert into public.report_media (report_id, media_url, mime_type, bytes)
    values (p_report,
            v_item ->> 'media_url',
            v_item ->> 'mime_type',
            (v_item ->> 'bytes')::integer);
  end loop;
end $$;


--
-- Name: FUNCTION request_reopen(p_report uuid, p_reason text, p_media jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.request_reopen(p_report uuid, p_reason text, p_media jsonb) IS 'The resident asks; the barangay decides. Notifies admins, writes the request to status_logs, and optionally attaches one evidence photo to report_media (0037) without changing the report''s status. SECURITY DEFINER for the same reason as cancel_report — the status_logs and report_media inserts are otherwise admin/owner-only under RLS.';


--
-- Name: retirement_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.retirement_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tanod_id uuid NOT NULL,
    status public.retirement_status DEFAULT 'pending'::public.retirement_status NOT NULL,
    requested_at timestamp with time zone DEFAULT now() NOT NULL,
    decided_at timestamp with time zone,
    decided_by uuid,
    denial_reason text
);


--
-- Name: TABLE retirement_requests; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.retirement_requests IS 'A tanod''s ask to end their service. Insert only via request_retirement(); decided only via finalize_retirement(). See 0052 header.';


--
-- Name: request_retirement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_retirement() RETURNS public.retirement_requests
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_user public.users%rowtype;
  v_req  public.retirement_requests%rowtype;
  a      record;
begin
  select * into v_user from public.users where id = auth.uid() for update;
  if not found then
    raise exception 'No such account';
  end if;

  if v_user.role <> 'tanod' then
    raise exception 'Only a tanod may request retirement';
  end if;

  if v_user.is_retired then
    raise exception 'This account has already retired';
  end if;

  if exists (
    select 1 from public.retirement_requests
     where tanod_id = v_user.id and status = 'pending'
  ) then
    raise exception 'A retirement request for this account is already waiting on the barangay';
  end if;

  insert into public.retirement_requests (tanod_id)
  values (v_user.id)
  returning * into v_req;

  for a in select id from public.users where role = 'admin' loop
    insert into public.notifications (user_id, kind, message)
    values (a.id, 'retirement',
            format('%s has requested retirement.', v_user.full_name));
  end loop;

  return v_req;
end $$;


--
-- Name: FUNCTION request_retirement(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.request_retirement() IS 'Tanod-only. Queues a retirement request and notifies every admin. Never changes users.is_retired itself — see finalize_retirement().';


--
-- Name: request_source(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_source() RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  -- The caller's address as Supabase's gateway saw it. cf-connecting-ip is
  -- set by Cloudflare and cannot be supplied by the client; the others are
  -- fallbacks. Null outside an API request (SQL editor, cron, tests).
  select nullif(trim(coalesce(
           h ->> 'cf-connecting-ip',
           split_part(h ->> 'x-forwarded-for', ',', 1),
           h ->> 'x-real-ip')), '')
    from (select nullif(current_setting('request.headers', true), '')::json as h) s
$$;


--
-- Name: reroute_dispatch(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reroute_dispatch(p_dispatch uuid, p_reason text, p_to uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_report   uuid;
  v_busy     text;
  v_resident uuid;
  v_tracking text;
begin
  if p_reason is null or char_length(trim(p_reason)) = 0 then
    raise exception 'A justification is required to reroute a dispatch';
  end if;

  -- Check the target before touching anything, so a refused hand-off
  -- leaves the original dispatch untouched rather than half-moved.
  if p_to is not null then
    select case when count(*) >= public.tanod_dispatch_cap() then max(r.subject) end into v_busy
      from public.dispatches d
      join public.reports r on r.id = d.report_id
     where d.tanod_id = p_to and d.state in ('assigned', 'accepted');

    if v_busy is not null then
      raise exception
        'That tanod already has the most dispatches a tanod can hold at once. Reroute to the queue instead.';
    end if;

    if not exists (select 1 from public.users
                    where id = p_to and is_dispatchable) then
      raise exception 'That tanod is not on duty and available';
    end if;
  end if;

  update public.dispatches
     set state = 'rerouted', rerouted_at = now(),
         reroute_reason = p_reason, rerouted_to = p_to
   where id = p_dispatch
     and tanod_id = auth.uid()
     and state in ('assigned', 'accepted')
  returning report_id into v_report;

  if v_report is null then
    raise exception 'Dispatch not found, not yours, or already actioned';
  end if;

  insert into public.status_logs (report_id, changed_by, old_status, new_status, remark)
  values (v_report, auth.uid(), 'assigned', 'assigned', 'Rerouted: ' || p_reason);

  if p_to is not null then
    insert into public.dispatches (report_id, tanod_id, assigned_by, admin_instructions)
    values (v_report, p_to, auth.uid(), 'Rerouted from a previous tanod.');

    insert into public.notifications (user_id, report_id, kind, message)
    values (p_to, v_report, 'reroute', 'A dispatch was rerouted to you.');

    -- NEW: a direct hand-off is a fresh dispatch for the resident too.
    select resident_id, tracking_id into v_resident, v_tracking
      from public.reports where id = v_report;

    insert into public.notifications (user_id, report_id, kind, message)
    values (v_resident, v_report, 'assignment',
            format('A tanod has been dispatched to your report %s.', v_tracking));
  else
    -- Back to the queue means back through proximity selection.
    -- redispatch_report -> auto_dispatch already notifies the resident
    -- once (and if) a new tanod is actually found, so nothing is added
    -- here â€” an intermediate "being rerouted" ping to the resident
    -- would be noise, not signal.
    perform public.redispatch_report(v_report, 'rerouted to queue: ' || p_reason);
  end if;

  insert into public.notifications (user_id, report_id, kind, message)
  select id, v_report, 'reroute', 'A dispatch was rerouted.'
    from public.users where role = 'admin';
end $$;


--
-- Name: reset_admin_password(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reset_admin_password(p_user uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'auth'
    AS $$
declare
  v_temp    text := public._temp_password();
  v_changed integer;
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may reset an administrator''s password';
  end if;
  if p_user = auth.uid() then
    raise exception 'Change your own password from Set a new password instead';
  end if;
  if not exists (select 1 from public.users where id = p_user and role = 'admin') then
    raise exception 'That account is not an administrator';
  end if;

  update auth.users
     set encrypted_password = extensions.crypt(v_temp, extensions.gen_salt('bf')), updated_at = now()
   where id = p_user;
  get diagnostics v_changed = row_count;
  if v_changed <> 1 then
    raise exception 'The password was not changed';
  end if;

  update public.users set must_change_password = true where id = p_user;

  insert into public.account_audit (subject_id, actor_id, action, detail)
  values (p_user, auth.uid(), 'password_reset', 'Temporary administrator password issued');

  return v_temp;
end $$;


--
-- Name: reset_verification_overdue_mark(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reset_verification_overdue_mark() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  if new.verification_status = 'pending'
     and old.verification_status is distinct from 'pending' then
    new.verification_overdue_notified_at := null;
  end if;
  return new;
end $$;


--
-- Name: resident_abuse_reports(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resident_abuse_reports(p_user uuid) RETURNS TABLE(report_id uuid, tracking_id text, subject text, remark text, flagged_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  select r.id, r.tracking_id, r.subject, sl.remark, sl.created_at
    from public.status_logs sl
    join public.reports r on r.id = sl.report_id
   where public.is_admin()
     and r.resident_id = p_user
     and sl.is_abusive = true
     and sl.new_status = 'rejected'
   order by sl.created_at desc
$$;


--
-- Name: FUNCTION resident_abuse_reports(p_user uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.resident_abuse_reports(p_user uuid) IS 'Every report rejected AND flagged abusive for one resident, newest first. Admin only -- the where clause returns zero rows rather than raising for anyone else, same style as tanod_roster()''s own guard.';


--
-- Name: resident_remark(text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resident_remark(p_remark text, p_is_system boolean) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select regexp_replace(regexp_replace(
    case
      when p_remark is null or btrim(p_remark) = '' then null
      when p_remark ~* '^(auto-dispatched|manually assigned)' then 'A tanod was assigned to your report.'
      when p_remark ~* '^(re-dispatching|rerouted)' then 'The barangay is sending another available tanod.'
      when p_remark ~* '^no tanod' then 'Waiting for an available tanod.'
      when p_remark ~* '^sla breach' then 'Past the expected date. The barangay has been alerted.'
      when p_remark ~* '^resolution target moved from' then 'The barangay changed the expected resolution date.'
      else p_remark
    end,
    '\m1 time\(s\)', '1 time', 'g'),
    'time\(s\)', 'times', 'g')
$$;


--
-- Name: FUNCTION resident_remark(p_remark text, p_is_system boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.resident_remark(p_remark text, p_is_system boolean) IS 'A status-log note as a resident should read it: assignment, re-dispatch and SLA notes (tanod names, distances, system jargon) become plain wording, and "time(s)" reads properly. 0099, 0105.';


--
-- Name: retirement_requests_queue(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.retirement_requests_queue() RETURNS TABLE(id uuid, tanod_id uuid, full_name text, email text, mobile_number text, status public.retirement_status, requested_at timestamp with time zone, decided_at timestamp with time zone, decided_by uuid, decided_by_name text, denial_reason text)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select r.id, r.tanod_id, u.full_name, u.email, u.mobile_number,
         r.status, r.requested_at, r.decided_at, r.decided_by, d.full_name,
         r.denial_reason
    from public.retirement_requests r
    join public.users u on u.id = r.tanod_id
    left join public.users d on d.id = r.decided_by
   order by (r.status = 'pending') desc, r.requested_at desc
$$;


--
-- Name: FUNCTION retirement_requests_queue(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.retirement_requests_queue() IS 'Retirement Requests queue. Pending first, newest first within that.';


--
-- Name: review_report(uuid, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.review_report(p_report uuid, p_decision text, p_remark text DEFAULT NULL::text, p_abusive boolean DEFAULT false) RETURNS public.report_status
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_report   public.reports%rowtype;
  v_new      report_status;
  v_remark   text := nullif(trim(coalesce(p_remark, '')), '');
  v_abusive  boolean;
  v_strikes  integer;
  v_resident public.users%rowtype;
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may review a complaint';
  end if;

  if p_decision not in ('validate', 'reject') then
    raise exception 'Unknown decision: %', p_decision;
  end if;

  select * into v_report
    from public.reports
   where id = p_report and deleted_at is null
     for update;

  if not found then
    raise exception 'No such report';
  end if;

  if v_report.status <> 'pending_review' then
    raise exception 'This complaint has already been reviewed (current status: %)',
      replace(v_report.status::text, '_', ' ');
  end if;

  if p_decision = 'reject' and v_remark is null then
    raise exception 'A reason is required when denying a complaint';
  end if;

  -- Only a reject can be abusive. A stray true on a validate call (there
  -- is no UI path that sends one, but nothing stops a direct RPC call)
  -- is silently dropped rather than raising -- this flag is additive
  -- bookkeeping, not something worth failing the whole review over.
  v_abusive := p_decision = 'reject' and coalesce(p_abusive, false);

  v_new := case p_decision when 'validate' then 'validated' else 'rejected' end::report_status;

  update public.reports
     set status = v_new
   where id = p_report;

  insert into public.status_logs
    (report_id, changed_by, old_status, new_status, remark, is_abusive)
  values
    (p_report, auth.uid(), v_report.status, v_new,
     coalesce(v_remark,
              'Complaint accepted for action by the barangay admin.'),
     v_abusive);

  insert into public.notifications (user_id, report_id, kind, message)
  values (v_report.resident_id, p_report, 'status_change',
          case p_decision
            when 'validate' then
              format('%s has been accepted and is now with the barangay.', v_report.tracking_id)
            else
              format('%s was not accepted. Reason: %s', v_report.tracking_id, v_remark)
          end);

  -- Auto-restriction. Counted fresh each time rather than kept as a
  -- running column on users -- this table is small per resident and a
  -- computed count can never drift out of sync with the log it is
  -- supposedly summarising, unlike a counter that has to be remembered
  -- to update everywhere the flag could change.
  if v_abusive then
    select count(*) into v_strikes
      from public.status_logs sl
      join public.reports r2 on r2.id = sl.report_id
     where r2.resident_id = v_report.resident_id
       and sl.is_abusive = true
       and sl.new_status = 'rejected';

    select * into v_resident from public.users where id = v_report.resident_id;

    if v_strikes >= 3 and v_resident.id is not null and not v_resident.is_suspended then
      perform public.set_account_suspension(
        v_report.resident_id,
        true,
        format('Automatically restricted: %s reports flagged as abusive.', v_strikes));
    end if;
  end if;

  return v_new;
end $$;


--
-- Name: FUNCTION review_report(p_report uuid, p_decision text, p_remark text, p_abusive boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.review_report(p_report uuid, p_decision text, p_remark text, p_abusive boolean) IS 'Validate Report / deny path, now with an optional abuse flag on a reject. At 3 abuse-flagged rejects for the same resident, calls set_account_suspension() itself -- same suspension, same RLS block on reports_resident_insert, same Reinstate button an admin already knows, just system-triggered instead of manual.';


--
-- Name: revoke_user_sessions(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_user_sessions(p_user uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
  -- Refresh tokens go with their session; an access token already issued
  -- runs out within the hour.
  delete from auth.sessions where user_id = p_user;
$$;


--
-- Name: FUNCTION revoke_user_sessions(p_user uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.revoke_user_sessions(p_user uuid) IS '0107: signs a user out on every device. Called by password-otp after an SMS password reset.';


--
-- Name: run_admin_handover_expirations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_admin_handover_expirations() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare r record;
begin
  for r in
    select id, full_name, admin_handover_role
      from public.users
     where role = 'admin'
       and admin_handover_until is not null
       and admin_handover_until <= now()
  loop
    begin
      update public.users
         set role                         = r.admin_handover_role,
             admin_handover_until         = null,
             admin_handover_role          = null,
             admin_handover_successor_id  = null
       where id = r.id;

      insert into public.account_audit (subject_id, actor_id, action, detail)
      values (r.id, null, 'stepped_down',
              format('Handover window ended automatically. Returned to %s.', r.admin_handover_role));

      insert into public.notifications (user_id, kind, message)
      values (r.id, 'verification',
              'Your administrator handover period has ended. You have been returned to your prior role.');
    exception when others then
      -- Leave this one's handover in place; the next hourly run tries
      -- again rather than losing the barangay's only administrator.
      continue;
    end;
  end loop;
end $$;


--
-- Name: run_media_cleanup(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_media_cleanup() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_url    text;
  v_secret text;
begin
  if to_regclass('vault.decrypted_secrets') is null then return; end if;
  execute $q$ select max(decrypted_secret) filter (where name = 'media_cleanup_url'),
                     max(decrypted_secret) filter (where name = 'media_cleanup_secret')
                from vault.decrypted_secrets $q$
     into v_url, v_secret;
  if v_url is null or v_secret is null then return; end if;
  if not exists (select 1 from public.media_trash where queued_at < now() - interval '7 days') then return; end if;
  perform net.http_post(url := v_url,
                        headers := jsonb_build_object('Content-Type', 'application/json', 'x-cleanup-secret', v_secret),
                        body := '{}'::jsonb,
                        timeout_milliseconds := 60000);
end $_$;


--
-- Name: set_accept_deadline(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_accept_deadline() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
declare mins integer;
begin
  if new.accept_due_at is null then
    select p.accept_minutes into mins
      from public.sla_policies p
      join public.reports r on r.category = p.category
     where r.id = new.report_id;
    if mins is not null then
      new.accept_due_at := new.assigned_at + make_interval(mins => mins);
    end if;
  end if;
  return new;
end $$;


--
-- Name: set_account_suspension(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_account_suspension(p_user uuid, p_suspend boolean, p_reason text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_user   public.users%rowtype;
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
  d        record;
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may suspend an account';
  end if;

  select * into v_user from public.users where id = p_user for update;
  if not found then
    raise exception 'No such account';
  end if;

  if p_user = auth.uid() then
    raise exception 'You cannot suspend your own account';
  end if;

  if v_user.role = 'admin' then
    raise exception 'Administrator accounts cannot be suspended from this screen';
  end if;

  if v_user.is_suspended = p_suspend then
    raise exception 'That account is already %',
      case when p_suspend then 'suspended' else 'active' end;
  end if;

  if p_suspend and v_reason is null then
    raise exception 'A reason is required when suspending an account';
  end if;

  update public.users
     set is_suspended     = p_suspend,
         suspended_reason = case when p_suspend then v_reason end
   where id = p_user;

  -- Suspending a tanod mid-incident cannot leave the complaint parked on
  -- a phone that will never open again. Same treatment as an acceptance
  -- window that elapsed: close the dispatch, put the report back in the
  -- queue, let proximity find someone else.
  if p_suspend and v_user.role = 'tanod' then
    for d in
      update public.dispatches
         set state = 'expired'
       where tanod_id = p_user and state in ('assigned', 'accepted')
      returning report_id
    loop
      perform public.redispatch_report(d.report_id, 'assigned tanod was suspended');
    end loop;
  end if;

  insert into public.notifications (user_id, kind, message)
  values (p_user,
          'verification',
          case when p_suspend
            then format('Your account has been suspended. Reason: %s', v_reason)
            else 'Your account has been reinstated.'
          end);

  return p_suspend;
end $$;


--
-- Name: FUNCTION set_account_suspension(p_user uuid, p_suspend boolean, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_account_suspension(p_user uuid, p_suspend boolean, p_reason text) IS 'Manage User Account suspend/reinstate. Releases any live dispatch the tanod was holding back to the queue.';


--
-- Name: set_dispatch_step(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_dispatch_step(p_dispatch uuid, p_step text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_d      public.dispatches%rowtype;
  v_status report_status;
  v_owner  uuid;
  v_tick   text;
  v_line   text;
begin
  if p_step not in ('on_the_way', 'arrived') then
    raise exception 'Unknown step';
  end if;

  select * into v_d from public.dispatches
   where id = p_dispatch and tanod_id = auth.uid() and state = 'accepted'
   for update;
  if not found then
    raise exception 'Dispatch not found, not yours, or not accepted';
  end if;

  if v_d.step = p_step or (v_d.step = 'arrived' and p_step = 'on_the_way') then
    return; -- already there; a double tap is not an error
  end if;

  update public.dispatches set step = p_step where id = p_dispatch;

  insert into public.dispatch_updates (dispatch_id, author_id, kind, step)
  values (p_dispatch, auth.uid(), 'step', p_step);

  select status, resident_id, tracking_id into v_status, v_owner, v_tick
    from public.reports where id = v_d.report_id;

  v_line := case p_step
              when 'on_the_way' then 'Tanod is on the way.'
              else 'Tanod has arrived.'
            end;

  insert into public.status_logs (report_id, changed_by, old_status, new_status, remark)
  values (v_d.report_id, auth.uid(), v_status, v_status, v_line);

  insert into public.notifications (user_id, report_id, kind, message)
  values (v_owner, v_d.report_id, 'status_change'::notification_kind,
          case p_step
            when 'on_the_way' then 'A tanod is on the way to ' || v_tick || '.'
            else 'The tanod has arrived for ' || v_tick || '.'
          end);
end $$;


--
-- Name: set_notification_mute(public.notification_kind, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_notification_mute(p_kind public.notification_kind, p_muted boolean) RETURNS public.notification_kind[]
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_out notification_kind[];
begin
  if v_uid is null then
    raise exception 'Not signed in';
  end if;

  if p_kind = 'verification' then
    raise exception 'Account-status notifications cannot be muted';
  end if;

  update public.users
     set muted_notification_kinds = case
           when p_muted then (
             select array_agg(distinct k) from (
               select unnest(coalesce(muted_notification_kinds, '{}')) as k
               union
               select p_kind
             ) t
           )
           else (
             select coalesce(array_agg(k), '{}') from (
               select unnest(coalesce(muted_notification_kinds, '{}')) as k
             ) t
             where k <> p_kind
           )
         end
   where id = v_uid
  returning muted_notification_kinds into v_out;

  if v_out is null then
    raise exception 'No such account';
  end if;

  return v_out;
end $$;


--
-- Name: FUNCTION set_notification_mute(p_kind public.notification_kind, p_muted boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_notification_mute(p_kind public.notification_kind, p_muted boolean) IS 'Self-service push-mute toggle, one kind at a time. verification is refused -- account-status changes are not muteable. Reading the current set needs no separate RPC: it is already on users, readable via the same self-select policy edit_profile_screen.dart already relies on.';


--
-- Name: set_report_deadline(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_report_deadline() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
declare hrs integer;
begin
  if new.due_at is null then
    select resolution_hours into hrs
      from public.sla_policies where category = new.category;
    if hrs is not null then
      new.due_at := new.created_at + make_interval(hours => hrs);
    end if;
  end if;
  return new;
end $$;


--
-- Name: FUNCTION set_report_deadline(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_report_deadline() IS 'Unused since 0071: the admin sets each complaint''s target date (set_resolution_target) before dispatching.';


--
-- Name: set_report_location_label(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_report_location_label(p_report uuid, p_label text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_owner uuid;
  v_label text := nullif(btrim(left(coalesce(p_label, ''), 160)), '');
begin
  if v_label is null then
    return false;
  end if;

  select resident_id into v_owner from public.reports where id = p_report;
  if not found then
    return false;
  end if;
  if v_owner is distinct from auth.uid() and coalesce(public.my_role()::text, '') <> 'admin' then
    raise exception 'not_allowed';
  end if;

  update public.reports
     set location_label = v_label
   where id = p_report
     and location_label is null;
  return found;
end $$;


--
-- Name: set_report_public(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_report_public(p_report uuid, p_public boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may publish an incident';
  end if;
  update public.reports set is_public = coalesce(p_public, false)
   where id = p_report and deleted_at is null;
  if not found then
    raise exception 'No such report';
  end if;
end $$;


--
-- Name: set_resolution_target(uuid, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_resolution_target(p_report uuid, p_due timestamp with time zone, p_reason text DEFAULT NULL::text) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_report public.reports%rowtype;
  v_when   text;
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
  v_cap    integer;
  v_used   integer;
  v_extend boolean;
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may change a resolution target';
  end if;

  select * into v_report from public.reports
   where id = p_report and deleted_at is null for update;
  if not found then
    raise exception 'No such report';
  end if;
  if p_due is null then
    raise exception 'A target date is required';
  end if;
  if p_due <= now() then
    raise exception 'The target date must be in the future';
  end if;
  if v_report.status in ('resolved', 'closed', 'archived', 'rejected', 'cancelled') then
    raise exception 'This complaint is already finished; its target cannot be moved';
  end if;
  if v_report.due_at is not distinct from p_due then
    return p_due;
  end if;

  -- Later than the current date: an extension, recorded and capped.
  v_extend := v_report.due_at is not null and p_due > v_report.due_at;
  if v_extend then
    select max_deadline_extensions into v_cap from public.operational_settings where id = 1;
    v_cap  := coalesce(v_cap, 2);
    v_used := public.extensions_used(p_report);
    if v_used >= v_cap then
      raise exception 'This complaint''s target date has already been extended % time(s), the limit. Hand it to a higher official instead.', v_used;
    end if;
    if v_reason is null or char_length(v_reason) < 5 or char_length(v_reason) > 300 then
      raise exception 'Give a reason (5 to 300 characters) for extending the target date';
    end if;
    insert into public.sla_extensions (report_id, requested_by, approved_by, previous_due, new_due, reason, approved_at)
    values (p_report, auth.uid(), auth.uid(), v_report.due_at, p_due, v_reason, now());
  end if;

  update public.reports set due_at = p_due where id = p_report;

  v_when := to_char(p_due at time zone 'Asia/Manila', 'FMMonth FMDD, YYYY, FMHH12:MI AM');

  insert into public.status_logs (report_id, changed_by, old_status, new_status, remark)
  values (p_report, auth.uid(), v_report.status, v_report.status,
          case when v_report.due_at is null
            then format('Expected to be resolved by %s.', v_when)
            else format('Expected resolution moved to %s.', v_when)
          end || case when v_extend then ' Reason: ' || v_reason else '' end);

  insert into public.notifications (user_id, report_id, kind, message)
  values (v_report.resident_id, p_report, 'status_change',
          case when v_report.due_at is null
            then format('The barangay expects to resolve %s by %s.', v_report.tracking_id, v_when)
            else format('The expected resolution of %s is now %s.', v_report.tracking_id, v_when)
          end);

  return p_due;
end $$;


--
-- Name: FUNCTION set_resolution_target(p_report uuid, p_due timestamp with time zone, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_resolution_target(p_report uuid, p_due timestamp with time zone, p_reason text) IS 'The admin sets or moves a complaint''s target date (0071). Moving it later is an extension (0079): it needs a reason, is recorded in sla_extensions, and is capped by max_deadline_extensions.';


--
-- Name: set_verification_deadline(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_verification_deadline() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  if new.verification_submitted_at is not null
     and (old.verification_submitted_at is null
          or old.verification_submitted_at is distinct from new.verification_submitted_at) then
    new.verification_due_at := new.verification_submitted_at + interval '2 hours';
  end if;
  return new;
end $$;


--
-- Name: status_logs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.status_logs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    report_id uuid NOT NULL,
    changed_by uuid,
    old_status public.report_status,
    new_status public.report_status NOT NULL,
    remark text,
    is_system boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    prev_hash text,
    entry_hash text,
    is_abusive boolean DEFAULT false NOT NULL
);


--
-- Name: COLUMN status_logs.entry_hash; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.status_logs.entry_hash IS 'SHA-256 over this entry and the previous entry_hash for the same report. See 0015.';


--
-- Name: COLUMN status_logs.is_abusive; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.status_logs.is_abusive IS 'Set only alongside a reject decision in review_report() -- an admin marking this specific denial as bad-faith (fabricated, malicious, spam) rather than an honest mistake (wrong barangay, duplicate, not enough detail). Meaningless on any other new_status; review_report() never sets it true for anything but a reject. Counted per resident to drive the 3-strike auto-restriction below.';


--
-- Name: status_log_fingerprint(public.status_logs); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.status_log_fingerprint(l public.status_logs) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select concat_ws('|',
    l.id::text, l.report_id::text, coalesce(l.changed_by::text, ''),
    coalesce(l.old_status::text, ''), l.new_status::text,
    coalesce(l.remark, ''), l.is_system::text,
    to_char(l.created_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US'))
$$;


--
-- Name: step_down_as_admin(public.user_role); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.step_down_as_admin(p_new_role public.user_role DEFAULT 'resident'::public.user_role) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_left integer;
  v_me   public.users%rowtype;
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may step down';
  end if;

  if p_new_role = 'admin' then
    raise exception 'Choose the role you are returning to, not administrator';
  end if;

  select * into v_me from public.users where id = auth.uid() for update;

  select count(*) into v_left from public.users
   where role = 'admin' and id <> auth.uid() and not is_suspended;

  -- The guard. Appoint your successor first; then this will let you go.
  if v_left = 0 then
    raise exception
      'You are the only administrator. Appoint your successor before stepping down, or the barangay will be locked out of its own system.';
  end if;

  update public.users set role = p_new_role where id = auth.uid();

  insert into public.account_audit (subject_id, actor_id, action, detail)
  values (v_me.id, v_me.id, 'stepped_down',
          format('Returned to %s. %s administrator(s) remain.', p_new_role, v_left));

  insert into public.notifications (user_id, kind, message)
  select id, 'verification',
         format('%s has stepped down as barangay administrator.', v_me.full_name)
    from public.users where role = 'admin' and id <> v_me.id;

  return v_left;
end $$;


--
-- Name: submit_additional_details(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_additional_details(p_request uuid, p_details text, p_media jsonb DEFAULT '[]'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_report    uuid;
  v_asker     uuid;
  v_answered  timestamptz;
  v_status    report_status;
  v_owner     uuid;
  v_ticket    text;
  v_details   text := nullif(trim(p_details), '');
  v_media     jsonb := coalesce(p_media, '[]'::jsonb);
  v_item      jsonb;
begin
  if jsonb_typeof(v_media) <> 'array' then
    raise exception 'p_media must be a JSON array of {media_url, mime_type, bytes}'
      using errcode = 'invalid_parameter_value';
  end if;
  if v_details is null and jsonb_array_length(v_media) = 0 then
    raise exception 'Please add the details or a photo';
  end if;
  if char_length(coalesce(v_details, '')) > 500 then
    raise exception 'Keep the details under 500 characters';
  end if;

  select q.report_id, q.requested_by, q.responded_at
    into v_report, v_asker, v_answered
    from public.detail_requests q
   where q.id = p_request;

  if v_report is null then
    raise exception 'Request not found';
  end if;

  select status, resident_id, tracking_id
    into v_status, v_owner, v_ticket
    from public.reports
   where id = v_report and deleted_at is null;

  if v_owner is distinct from auth.uid() then
    raise exception 'Only the resident who filed this report can answer';
  end if;
  if v_answered is not null then
    raise exception 'This request has already been answered';
  end if;
  if v_status not in ('assigned', 'in_progress', 'offline_investigation') then
    raise exception 'This report is no longer being worked on';
  end if;

  update public.detail_requests
     set response = v_details,
         responded_at = now()
   where id = p_request;

  -- Same insert idiom as request_reopen (0037): report_media_cap and
  -- the URL pins still apply.
  for v_item in select value from jsonb_array_elements(v_media)
  loop
    insert into public.report_media (report_id, media_url, mime_type, bytes)
    values (v_report,
            v_item ->> 'media_url',
            v_item ->> 'mime_type',
            (v_item ->> 'bytes')::integer);
  end loop;

  insert into public.status_logs
    (report_id, changed_by, old_status, new_status, remark)
  values
    (v_report, auth.uid(), v_status, v_status,
     'Resident sent more details: ' ||
       coalesce(v_details, 'photo/video attached'));

  -- Whoever asked, and the tanod now holding the case if that's someone
  -- else (a reroute in between).
  insert into public.notifications (user_id, report_id, kind, message)
  -- (the union already drops a duplicate recipient)
  select u, v_report, 'status_change'::notification_kind,
         'The resident sent more details for ' || v_ticket || '.'
    from (
      select v_asker as u
      union
      select d.tanod_id from public.dispatches d
       where d.report_id = v_report and d.state = 'accepted'
    ) t
   where u is not null;
end $$;


--
-- Name: FUNCTION submit_additional_details(p_request uuid, p_details text, p_media jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.submit_additional_details(p_request uuid, p_details text, p_media jsonb) IS 'The resident answers an open detail request with text and/or media (into report_media under the usual caps and URL pins). Logs to status_logs and notifies the asker and the current tanod. 0065.';


--
-- Name: submit_field_report(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_field_report(p_dispatch uuid, p_text text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_report uuid; v_status report_status; v_tick text;
begin
  update public.dispatches
     set state = 'resolved', field_report_text = p_text, resolved_at = now()
   where id = p_dispatch and tanod_id = auth.uid() and state = 'accepted'
  returning report_id into v_report;

  if v_report is null then
    raise exception 'Dispatch not found, not yours, or not in an accepted state';
  end if;

  update public.reports
     set resolution_submitted_at = now(), resolution_returned_reason = null
   where id = v_report
  returning status, tracking_id into v_status, v_tick;

  insert into public.status_logs (report_id, changed_by, old_status, new_status, remark)
  values (v_report, auth.uid(), v_status, v_status,
          'Resolution report submitted by the tanod, waiting for the barangay''s approval.');

  insert into public.notifications (user_id, report_id, kind, message)
  select u.id, v_report, 'status_change',
         'A tanod submitted the resolution of ' || v_tick || '. Review and approve it.'
    from public.users u where u.role = 'admin';
end $$;


--
-- Name: sweep_awaiting_units(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sweep_awaiting_units() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  r      record;
  v_hours smallint;
begin
  select awaiting_alert_hours into v_hours from public.operational_settings where id = 1;

  for r in
    select id, awaiting_unit_since
      from public.reports
     where awaiting_unit_since is not null
       and deleted_at is null
       and status in ('pending_review', 'validated')
     order by awaiting_unit_since
  loop
    if r.awaiting_unit_since < now() - make_interval(hours => v_hours)
       and not exists (
         select 1 from public.notifications n
          where n.report_id = r.id and n.kind = 'escalation') then
      insert into public.notifications (user_id, report_id, kind, message)
      select u.id, r.id, 'escalation',
             format('A report has been waiting over %s hours with no tanod on duty in range.', v_hours)
        from public.users u where u.role = 'admin';
    end if;

    perform public.auto_dispatch(r.id);
  end loop;
end $$;


--
-- Name: sweep_overdue_reports(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sweep_overdue_reports() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  with late as (
    update public.reports
       set overdue_notified_at = now()
     where due_at is not null
       and due_at < now()
       and (overdue_notified_at is null or overdue_notified_at < due_at)
       and status not in ('resolved', 'closed', 'archived', 'rejected', 'cancelled')
       and deleted_at is null
    returning id, tracking_id
  ),
  to_admins as (
    insert into public.notifications (user_id, report_id, kind, message)
    select u.id, l.id, 'sla_warning',
           'Complaint ' || l.tracking_id || ' is overdue: its target date has passed.'
      from late l cross join public.users u
     where u.role = 'admin'
    returning 1
  )
  insert into public.notifications (user_id, report_id, kind, message)
  select d.tanod_id, l.id, 'sla_warning',
         'Your dispatch ' || l.tracking_id || ' is overdue: its target date has passed.'
    from late l
    join public.dispatches d on d.report_id = l.id and d.state in ('assigned', 'accepted');
end $$;


--
-- Name: FUNCTION sweep_overdue_reports(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sweep_overdue_reports() IS '0072: tells admins and the dispatched tanod once when an admin-set deadline passes. Escalation is the admin''s referral (refer_report).';


--
-- Name: sweep_overdue_verifications(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sweep_overdue_verifications() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  -- Mark first and notify from what was marked, matching the shape of
  -- the other two sweeps. A row can only be returned by the UPDATE once,
  -- so it can only generate one round of notifications however often
  -- this runs.
  with newly_overdue as (
    update public.users u
       set verification_overdue_notified_at = now()
     where u.verification_status = 'pending'
       and u.verification_due_at < now()
       and u.verification_overdue_notified_at is null
    returning u.id, u.full_name
  )
  insert into public.notifications (user_id, kind, message)
  select a.id, 'sla_warning',
         'Account verification for ' || n.full_name
           || ' has passed the 2-hour limit.'
    from newly_overdue n
    cross join public.users a
   where a.role = 'admin'
     and not a.is_suspended;
end $$;


--
-- Name: FUNCTION sweep_overdue_verifications(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sweep_overdue_verifications() IS 'Notifies admins once per account when its two-hour verification window elapses. Idempotent: the UPDATE that marks the account is what drives the notification, so repeated runs cannot duplicate it.';


--
-- Name: sweep_unaccepted_dispatches(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sweep_unaccepted_dispatches() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare r record;
begin
  for r in
    update public.dispatches
       set state = 'expired'
     where state = 'assigned' and accept_due_at < now()
    returning id, report_id, tanod_id
  loop
    insert into public.notifications (user_id, report_id, kind, message)
    select u.id, r.report_id, 'sla_warning',
           'A tanod did not respond to a dispatch within the acceptance window.'
      from public.users u where u.role = 'admin';

    -- The report does not stay parked on a dispatch nobody accepted.
    perform public.redispatch_report(r.report_id, 'acceptance window elapsed');
  end loop;
end $$;


--
-- Name: sync_dispatchable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_dispatchable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  new.is_dispatchable := coalesce(
    new.role = 'tanod'
    and new.duty_status = 'on_duty'
    and new.verification_status = 'verified'
    and not new.is_suspended
    and not new.is_retired, false);
  return new;
end $$;


--
-- Name: system_usage(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.system_usage() RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  month_start timestamptz := date_trunc('month', now() at time zone 'Asia/Manila') at time zone 'Asia/Manila';
begin
  if not public.is_admin() then
    raise exception 'admins only';
  end if;
  return json_build_object(
    'db_bytes',      pg_database_size(current_database()),
    'storage_bytes', coalesce((select sum((metadata->>'size')::bigint) from storage.objects), 0),
    'active_users',  (select count(*) from auth.users where last_sign_in_at >= month_start),
    'month_start',   month_start
  );
end $$;


--
-- Name: take_case(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.take_case(p_report uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_h uuid; v_name text;
begin
  if not public.is_admin() then raise exception 'Only an administrator may take a case'; end if;
  select handler_id into v_h from public.reports where id = p_report and deleted_at is null for update;
  if not found then raise exception 'No such report'; end if;
  if v_h = auth.uid() then return; end if;
  if v_h is not null then
    select public.display_name(full_name) into v_name from public.users where id = v_h;
    raise exception '% is already handling this case. Use Take over.', coalesce(v_name, 'Another administrator');
  end if;
  perform set_config('smartsumbong.handler_change', 'on', true);
  update public.reports set handler_id = auth.uid(), handled_since = now() where id = p_report;
  perform set_config('smartsumbong.handler_change', 'off', true);
  insert into public.case_handler_log (report_id, admin_id, action) values (p_report, auth.uid(), 'take');
end $$;


--
-- Name: take_over_case(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.take_over_case(p_report uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_h      uuid;
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
  v_me     text;
  v_track  text;
begin
  if not public.is_admin() then raise exception 'Only an administrator may take over a case'; end if;
  if v_reason is null or char_length(v_reason) < 3 or char_length(v_reason) > 300 then
    raise exception 'Give a reason for taking over (the current handler sees it)';
  end if;
  select handler_id, tracking_id into v_h, v_track from public.reports where id = p_report and deleted_at is null for update;
  if not found then raise exception 'No such report'; end if;
  if v_h = auth.uid() then return; end if;
  perform set_config('smartsumbong.handler_change', 'on', true);
  update public.reports set handler_id = auth.uid(), handled_since = now() where id = p_report;
  perform set_config('smartsumbong.handler_change', 'off', true);
  insert into public.case_handler_log (report_id, admin_id, action, previous_id, reason)
  values (p_report, auth.uid(), case when v_h is null then 'take' else 'take_over' end, v_h, v_reason);
  if v_h is not null then
    select public.display_name(full_name) into v_me from public.users where id = auth.uid();
    insert into public.notifications (user_id, report_id, kind, message)
    values (v_h, p_report, 'status_change', coalesce(v_me, 'Another administrator') || ' took over ' || v_track || ' from you: ' || v_reason);
  end if;
end $$;


--
-- Name: take_rate_slot(text, integer, interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.take_rate_slot(p_bucket text, p_max integer, p_window interval) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_now  timestamptz := now();
  v_hits integer;
begin
  insert into public.rate_limit_hits as r (bucket, window_start, hits)
  values (p_bucket, v_now, 1)
  on conflict (bucket) do update
     set hits = case when r.window_start < v_now - p_window then 1 else r.hits + 1 end,
         window_start = case when r.window_start < v_now - p_window then v_now else r.window_start end
  returning hits into v_hits;

  if v_hits = 1 then
    delete from public.rate_limit_hits where window_start < v_now - interval '1 day';
  end if;
  return v_hits <= p_max;
end $$;


--
-- Name: FUNCTION take_rate_slot(p_bucket text, p_max integer, p_window interval); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.take_rate_slot(p_bucket text, p_max integer, p_window interval) IS '0109: true while bucket has had at most p_max calls in the current p_window. Edge Functions only (service role).';


--
-- Name: tanod_dispatch_cap(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tanod_dispatch_cap() RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select coalesce((select max_active_dispatches from public.operational_settings limit 1), 5)
$$;


--
-- Name: tanod_roster(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tanod_roster(p_report uuid) RETURNS TABLE(tanod_id uuid, full_name text, duty_status public.duty_state, assignable boolean, unavailable_why text, metres double precision, location_fresh boolean)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select u.id,
         u.full_name,
         u.duty_status,
         u.is_dispatchable and coalesce(b.n, 0) < public.tanod_dispatch_cap(),
         case
           when coalesce(b.n, 0) >= public.tanod_dispatch_cap() then 'Has ' || b.n || ' dispatches (the most at once)'
           when u.is_suspended                then 'Suspended'
           when u.verification_status <> 'verified' then 'Not yet verified'
           when coalesce(u.duty_status, 'offline') <> 'on_duty'
             then initcap(replace(coalesce(u.duty_status, 'offline')::text, '_', ' '))
           else null
         end,
         st_distance(u.last_geom, r.geom),
         public.location_is_fresh(u.last_location_at)
    from public.users u
    cross join public.reports r
    left join lateral (
      select count(*)::int as n from public.dispatches d
       where d.tanod_id = u.id and d.state in ('assigned', 'accepted')) b on true
   where r.id = p_report
     and u.role = 'tanod'
   order by (u.is_dispatchable and coalesce(b.n, 0) < public.tanod_dispatch_cap()) desc,
            coalesce(b.n, 0),
            st_distance(u.last_geom, r.geom) nulls last,
            u.full_name
$$;


--
-- Name: FUNCTION tanod_roster(p_report uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.tanod_roster(p_report uuid) IS 'Every tanod with availability and distance, for the assign screen. Available first, then nearest. assignable_tanods remains the authoritative "who may take this".';


--
-- Name: touch_settings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.touch_settings() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  new.updated_at := now();
  new.updated_by := auth.uid();
  return new;
end $$;


