-- Name: touch_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.touch_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  new.updated_at := now();
  return new;
end $$;


--
-- Name: unregister_device_token(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unregister_device_token(p_token text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'Not signed in';
  end if;
  delete from public.device_tokens
   where user_id = auth.uid() and fcm_token = p_token;
end $$;


--
-- Name: update_my_location(double precision, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_my_location(p_lat double precision, p_lon double precision) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_geom geography(Point, 4326) :=
    st_setsrid(st_makepoint(p_lon, p_lat), 4326)::geography;
begin
  if auth.uid() is null then
    raise exception 'Not signed in';
  end if;

  update public.users
     set last_geom = v_geom,
         last_location_at = now()
   where id = auth.uid()
     and role = 'tanod'
     and duty_status = 'on_duty';

  if not found then
    raise exception 'Location is only recorded for a tanod who is on duty';
  end if;
end $$;


--
-- Name: users_queue_media_trash(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.users_queue_media_trash() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'DELETE' then
    perform public.queue_media_trash(old.id_image_url);
    perform public.queue_media_trash(old.selfie_url);
    perform public.queue_media_trash(old.avatar_url);
    return old;
  end if;
  if old.id_image_url is distinct from new.id_image_url then perform public.queue_media_trash(old.id_image_url); end if;
  if old.selfie_url   is distinct from new.selfie_url   then perform public.queue_media_trash(old.selfie_url); end if;
  if old.avatar_url   is distinct from new.avatar_url   then perform public.queue_media_trash(old.avatar_url); end if;
  return new;
end $$;


--
-- Name: verify_report_trail(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_report_trail(p_report uuid) RETURNS TABLE(entry_no integer, logged_at timestamp with time zone, change text, intact boolean, problem text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  l       public.status_logs%rowtype;
  v_calc  text;
  v_known boolean;
  n       integer := 0;
begin
  -- No signed-in user is the database itself (audit_integrity(), the SQL
  -- editor, the service role); a signed-in caller must be an admin or the
  -- complainant (0080/0081).
  if auth.uid() is not null and not (public.is_admin()
          or exists (select 1 from public.reports r
                      where r.id = p_report and r.resident_id = auth.uid())) then
    raise exception 'Only an administrator or the complainant may verify this trail';
  end if;

  for l in select * from public.status_logs
            where report_id = p_report
            order by created_at, id loop
    n := n + 1;
    v_calc := case when l.prev_hash is null then null
                   else encode(digest(l.prev_hash || '|' || public.status_log_fingerprint(l), 'sha256'), 'hex') end;
    v_known := l.prev_hash = repeat('0', 64)
               or exists (select 1 from public.status_logs p
                           where p.report_id = p_report and p.entry_hash = l.prev_hash);

    entry_no  := n;
    logged_at := l.created_at;
    change    := coalesce(l.old_status::text, 'filed') || ' → ' || l.new_status::text;
    intact    := l.entry_hash is not null and l.entry_hash = v_calc and v_known;
    problem   := case
                   when l.entry_hash is null then 'No hash recorded'
                   when l.entry_hash <> v_calc then 'This entry was altered after it was written'
                   when not v_known then 'Chain broken — the entry before this one was changed or removed'
                 end;
    return next;
  end loop;
end $$;


--
-- Name: FUNCTION verify_report_trail(p_report uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.verify_report_trail(p_report uuid) IS 'Checks one complaint''s hash chain (0082): every entry''s hash matches its content and link, and the entry it links to still exists. Admins, the complainant, or the database itself.';


--
-- Name: verify_user_account(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_user_account(p_user uuid, p_decision text, p_reason text DEFAULT NULL::text) RETURNS public.verification_state
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_user   public.users%rowtype;
  v_new    verification_state;
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may verify an account';
  end if;

  if p_decision not in ('approve', 'deny') then
    raise exception 'Unknown decision: %', p_decision;
  end if;

  select * into v_user from public.users where id = p_user for update;
  if not found then
    raise exception 'No such account';
  end if;

  if v_user.role = 'admin' then
    raise exception 'Administrator accounts are not verified through this queue';
  end if;

  if v_user.verification_status <> 'pending' then
    raise exception 'This account has already been reviewed (current status: %)',
      v_user.verification_status;
  end if;

  -- A rejection the applicant cannot act on just produces a second
  -- identical registration an hour later.
  if p_decision = 'deny' and v_reason is null then
    raise exception 'A reason is required when denying an account';
  end if;

  v_new := case p_decision when 'approve' then 'verified' else 'rejected' end::verification_state;

  update public.users
     set verification_status = v_new,
         verified_at         = case when v_new = 'verified' then now() end,
         verified_by         = auth.uid(),
         rejection_reason    = v_reason
   where id = p_user;

  insert into public.notifications (user_id, kind, message)
  values (p_user, 'verification',
          case p_decision
            when 'approve' then
              'Your Smart Sumbong account has been verified. You may now file a complaint.'
            else
              format('Your registration was not approved. Reason: %s', v_reason)
          end);

  return v_new;
end $$;


--
-- Name: FUNCTION verify_user_account(p_user uuid, p_decision text, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.verify_user_account(p_user uuid, p_decision text, p_reason text) IS 'Verify User Account. Admin only, pending only. Status, audit fields and applicant notification in one transaction.';


