--

COMMENT ON TABLE public.device_tokens IS 'One row per (user, installed app) FCM registration. Written only via register_device_token()/unregister_device_token() — never directly, so a user can only ever register a token against their own account. Read by supabase/functions/send-dispatch-push using the service role key, which bypasses RLS by design.';


--
-- Name: dispatch_media; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.dispatch_media (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    dispatch_id uuid NOT NULL,
    media_url text NOT NULL,
    mime_type text NOT NULL,
    bytes integer NOT NULL,
    uploaded_at timestamp with time zone DEFAULT now() NOT NULL,
    update_id uuid,
    CONSTRAINT dispatch_media_bytes_check CHECK (((bytes > 0) AND (bytes <= ((25 * 1024) * 1024)))),
    CONSTRAINT dispatch_media_mime_type_check CHECK ((mime_type = ANY (ARRAY['image/jpeg'::text, 'image/png'::text, 'video/mp4'::text, 'video/quicktime'::text, 'video/webm'::text, 'video/3gpp'::text]))),
    CONSTRAINT dispatch_media_url_folder CHECK ((media_url ~ '^https://res\.cloudinary\.com/nwb2kryl/(image|video)/upload/v[0-9]+/dispatch/'::text)),
    CONSTRAINT dispatch_media_url_pinned CHECK (public.is_evidence_media_url(media_url))
);


--
-- Name: TABLE dispatch_media; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.dispatch_media IS 'Tanod field photographs. Readable by the tanod who submitted them, by admins, and — since 0024 — by the resident whose complaint they evidence, because the Completed view promises them proof and a complaint system that cannot show its work is not one.';


--
-- Name: dispatch_updates; Type: TABLE; Schema: public; Owner: -
