    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT dispatch_updates_body_check CHECK (((body IS NULL) OR (char_length(body) <= 2000))),
    CONSTRAINT dispatch_updates_kind_check CHECK ((kind = ANY (ARRAY['note'::text, 'step'::text]))),
    CONSTRAINT dispatch_updates_shape CHECK ((((kind = 'step'::text) AND (step IS NOT NULL)) OR ((kind = 'note'::text) AND (step IS NULL)))),
    CONSTRAINT dispatch_updates_step_check CHECK ((step = ANY (ARRAY['on_the_way'::text, 'arrived'::text])))
);


--
-- Name: TABLE dispatch_updates; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.dispatch_updates IS 'The dispatch window thread (0069): tanod notes, admin replies and the On the way / Arrived steps. Readable by the dispatched tanod and admins; written only through post_dispatch_update() and set_dispatch_step().';


--
-- Name: dispatches; Type: TABLE; Schema: public; Owner: -
