    step text,
    CONSTRAINT dispatches_admin_instructions_check CHECK ((char_length(admin_instructions) <= 500)),
    CONSTRAINT dispatches_field_report_text_check CHECK ((char_length(field_report_text) <= 300)),
    CONSTRAINT dispatches_reroute_reason_check CHECK ((char_length(reroute_reason) <= 200)),
    CONSTRAINT dispatches_step_check CHECK ((step = ANY (ARRAY['on_the_way'::text, 'arrived'::text]))),
    CONSTRAINT reroute_needs_reason CHECK (((rerouted_at IS NULL) OR (reroute_reason IS NOT NULL)))
);


