    CONSTRAINT operational_settings_max_active_dispatches_check CHECK (((max_active_dispatches >= 1) AND (max_active_dispatches <= 20))),
    CONSTRAINT operational_settings_max_deadline_extensions_check CHECK (((max_deadline_extensions >= 0) AND (max_deadline_extensions <= 10))),
    CONSTRAINT operational_settings_max_dispatch_attempts_check CHECK (((max_dispatch_attempts >= 1) AND (max_dispatch_attempts <= 10))),
    CONSTRAINT operational_settings_max_report_photos_check CHECK (((max_report_photos >= 1) AND (max_report_photos <= 20))),
    CONSTRAINT operational_settings_max_reports_per_day_check CHECK (((max_reports_per_day >= 1) AND (max_reports_per_day <= 200)))
);


--
-- Name: TABLE operational_settings; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.operational_settings IS 'Operational policy owned by the barangay, not the developer. Single row.';


--
-- Name: COLUMN operational_settings.max_report_photos; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.operational_settings.max_report_photos IS 'Photos per complaint. Enforced because row counts are verifiable; the 10 MB byte cap is not, because bytes is client-asserted.';


--
-- Name: COLUMN operational_settings.max_deadline_extensions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.operational_settings.max_deadline_extensions IS 'How many times a complaint''s target date may be moved later before it must be handed to a higher official (0079).';


--
-- Name: COLUMN operational_settings.max_reports_per_day; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.operational_settings.max_reports_per_day IS '0107: most reports one resident may file in any 24 hours.';


