    CONSTRAINT profile_requests_new_full_name_check CHECK (((char_length(new_full_name) >= 3) AND (char_length(new_full_name) <= 120))),
    CONSTRAINT profile_requests_reason_check CHECK ((char_length(reason) <= 300)),
    CONSTRAINT profile_requests_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'declined'::text])))
);


