    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT extension_moves_forward CHECK ((new_due > previous_due)),
    CONSTRAINT sla_extensions_reason_check CHECK (((char_length(reason) >= 5) AND (char_length(reason) <= 300)))
);


--
-- Name: sla_policies; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sla_policies (
    category public.complaint_category NOT NULL,
    resolution_hours integer NOT NULL,
    accept_minutes integer NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    auto_dispatch_on_file boolean DEFAULT false NOT NULL,
    CONSTRAINT sla_policies_accept_minutes_check CHECK ((accept_minutes > 0)),
    CONSTRAINT sla_policies_resolution_hours_check CHECK ((resolution_hours > 0))
);


--
-- Name: TABLE sla_policies; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.sla_policies IS 'Per-category SLA windows. resolution_hours drives reports.due_at; accept_minutes drives dispatches.accept_due_at. Values are placeholders pending barangay confirmation.';


--
-- Name: COLUMN sla_policies.auto_dispatch_on_file; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sla_policies.auto_dispatch_on_file IS 'Unused since 0070: every dispatch is assigned by an admin. Kept so older readers do not break.';


