ALTER TABLE public.retirement_requests ENABLE ROW LEVEL SECURITY;

--
-- Name: retirement_requests retirement_requests_admin_write; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY retirement_requests_admin_write ON public.retirement_requests USING (( SELECT public.is_admin() AS is_admin)) WITH CHECK (( SELECT public.is_admin() AS is_admin));


--
-- Name: retirement_requests retirement_requests_read; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY retirement_requests_read ON public.retirement_requests FOR SELECT USING (((tanod_id = ( SELECT auth.uid() AS uid)) OR ( SELECT public.is_admin() AS is_admin)));


