--
-- Name: operational_settings settings_write; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY settings_write ON public.operational_settings FOR UPDATE USING (( SELECT public.is_admin() AS is_admin)) WITH CHECK (( SELECT public.is_admin() AS is_admin));


