--
-- Name: status_logs; Type: ROW SECURITY; Schema: public; Owner: -
--

ALTER TABLE public.status_logs ENABLE ROW LEVEL SECURITY;

--
-- Name: status_logs status_logs_insert; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY status_logs_insert ON public.status_logs FOR INSERT WITH CHECK ((( SELECT public.is_admin() AS is_admin) AND (changed_by = ( SELECT auth.uid() AS uid)) AND (is_system = false)));


--
-- Name: status_logs status_logs_read; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY status_logs_read ON public.status_logs FOR SELECT USING ((( SELECT public.is_admin() AS is_admin) OR (EXISTS ( SELECT 1
   FROM public.reports r
  WHERE ((r.id = status_logs.report_id) AND (r.resident_id = ( SELECT auth.uid() AS uid))))) OR (EXISTS ( SELECT 1
   FROM public.dispatches d
  WHERE ((d.report_id = status_logs.report_id) AND (d.tanod_id = ( SELECT auth.uid() AS uid)))))));


