-- Triggers on auth.users (signup and the synthetic sign-in address).
CREATE TRIGGER auth_users_confirm_synthetic BEFORE INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.confirm_synthetic_auth_email();
CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_auth_user();

-- Realtime.
do $$ begin if not exists (select 1 from pg_publication where pubname = 'supabase_realtime') then create publication supabase_realtime; end if; end $$;
alter publication supabase_realtime add table public.case_handler_log;
alter publication supabase_realtime add table public.detail_requests;
alter publication supabase_realtime add table public.dispatch_updates;
alter publication supabase_realtime add table public.dispatches;
alter publication supabase_realtime add table public.escalation_requests;
alter publication supabase_realtime add table public.notifications;
alter publication supabase_realtime add table public.report_messages;
alter publication supabase_realtime add table public.reports;
alter publication supabase_realtime add table public.retirement_requests;
alter publication supabase_realtime add table public.status_logs;

-- Scheduled jobs.
select cron.schedule('keep-portal-awake', '*/10 * * * *', ' select public.ping_portal() ');
select cron.schedule('media-cleanup', '40 3 * * *', ' select public.run_media_cleanup() ');
select cron.schedule('purge-old-notifications', '20 3 * * *', ' select public.purge_old_notifications() ');
select cron.schedule('sweep-admin-handovers', '0 * * * *', 'select public.run_admin_handover_expirations()');
select cron.schedule('sweep-awaiting-units', '*/2 * * * *', 'select public.sweep_awaiting_units()');
select cron.schedule('sweep-overdue-reports', '*/15 * * * *', 'select public.sweep_overdue_reports()');
select cron.schedule('sweep-overdue-verifications', '*/10 * * * *', 'select public.sweep_overdue_verifications()');
select cron.schedule('sweep-unaccepted-dispatches', '*/5  * * * *', 'select public.sweep_unaccepted_dispatches()');

-- Supabase's defaults back on for whatever comes next.
alter default privileges in schema public grant all on tables to anon, authenticated, service_role;
alter default privileges in schema public grant all on sequences to anon, authenticated, service_role;
alter default privileges in schema public grant all on functions to anon, authenticated, service_role;
